window.PHYSICS={"sections":["Методы познания","Механика","Колебания и волны","Тепловая физика","Электричество","Электромагнетизм","Оптика","Квантовая физика","Современная физика"],"topics":[{"id":"topic-0","name":"Измерения и единицы","section":"Методы познания","cards":[{"id":"ege-physics-0-formula","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы\nЗапиши формулу плотности ρ через массу m и объём V.","back":"Ответ: rho=m/V.\n\nПлотность показывает массу единицы объёма: ρ = m/V. В СИ масса в кг, объём в м³, плотность в кг/м³.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":0},"hint":"Раздели массу на объём. Не смешивай граммы с килограммами.","formula":"rho=m/V","formulaSide":"back","source":"Физика с котом: Измерения и единицы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Измерения и единицы"},{"id":"ege-physics-0-easy","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы\nВ 2 см³ вещества содержится 10 г. Какова плотность?","back":"Ответ: 5 г/см³.\n\nρ = m/V = 10/2 = 5 г/см³.","hints":["Раздел «Измерения и единицы». Отделите искомую величину от данных условия. Ответ требуется в г/см³.","Используйте связь rho=m/V. Выразите искомую величину до подстановки чисел. Раздели массу на объём. Не смешивай граммы с килограммами."],"answerSpec":{"kind":"number","value":5,"unit":"г/см³"},"hint":"Раздели массу на объём. Не смешивай граммы с килограммами.","source":"Физика с котом: Измерения и единицы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Измерения и единицы"},{"id":"ege-physics-0-task","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы\nМасса образца 120 г, объём 40 см³. Найди плотность в г/см³.","back":"Ответ: 3 г/см³.\n\nПо определению: ρ = 120/40 = 3 г/см³.\n\nЧерез СИ: m = 0,12 кг, V = 0,00004 м³; ρ = 3000 кг/м³ = 3 г/см³.","hints":["Раздел «Измерения и единицы». Отделите искомую величину от данных условия. Ответ требуется в г/см³.","Используйте связь rho=m/V. Выразите искомую величину до подстановки чисел. Раздели массу на объём. Не смешивай граммы с килограммами."],"answerSpec":{"kind":"number","value":3,"unit":"г/см³"},"hint":"Раздели массу на объём. Не смешивай граммы с килограммами.","source":"Физика с котом: Измерения и единицы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Измерения и единицы"},{"id":"ege-physics-0-bonus","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы · Повышенная сложность\nИзмерено: m = (100 ± 2) г, V = (20 ± 1) см³. Оцени максимальную относительную погрешность плотности в процентах по правилу сложения относительных погрешностей.","back":"Ответ: 7 %.\n\nδρ ≈ δm + δV = 2/100 + 1/20 = 0,07 = 7%. Это приближённая оценка для малых погрешностей, как и требует условие.","hints":["Раздел «Измерения и единицы». Отделите искомую величину от данных условия. Ответ требуется в %.","Используйте связь rho=m/V. Выразите искомую величину до подстановки чисел. Раздели массу на объём. Не смешивай граммы с килограммами."],"answerSpec":{"kind":"number","value":7,"unit":"%"},"hint":"Раздели массу на объём. Не смешивай граммы с килограммами.","source":"Физика с котом: Измерения и единицы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Измерения и единицы"},{"id":"ege-physics-0-meaning-0","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы: объясни формулу rho=m/V. Что означают величины и когда её применять?","back":"Ро равно эм делить на вэ.\n\nρ (ро): плотность; m (эм): масса; V (вэ): объём.\n\nПлотность показывает массу единицы объёма. 1 г/см³ = 1000 кг/м³.","formula":"rho=m/V","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Раздели массу на объём. Не смешивай граммы с килограммами.","source":"Физика с котом: Измерения и единицы","objective":"Измерения и единицы"},{"id":"ege-physics-0-meaning-1","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы: объясни формулу deltaM=dm/m. Что означают величины и когда её применять?","back":"Относительная погрешность массы равна абсолютной погрешности массы, делённой на массу.\n\nВ этой карточке используем запись δₘ = Δm/m: δ (маленькая дельта) обозначает относительную погрешность; Δ (большая дельта) перед m обозначает абсолютную погрешность.\n\nДля массы 100 ± 2 г относительная погрешность равна 2/100 = 0,02, то есть 2%.","formula":"deltaM=dm/m","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Раздели массу на объём. Не смешивай граммы с килограммами.","source":"Физика с котом: Измерения и единицы","objective":"Измерения и единицы"},{"id":"ege-physics-0-notes","topic":"ЕГЭ Физика · Методы познания","front":"Измерения и единицы: какие условия применимости и типичные ошибки нужно помнить?","back":"1 см³ = 10⁻⁶ м³; 1 г/см³ = 1000 кг/м³. Цена деления = разность соседних подписанных значений / число промежутков. Погрешность прибора задаётся условием, она не всегда равна половине деления. Для проверки зависимости меняй один фактор, остальные сохраняй.","source":"Физика с котом: Измерения и единицы","objective":"Измерения и единицы"}]},{"id":"topic-1","name":"Кинематика","section":"Механика","cards":[{"id":"ege-physics-1-formula","topic":"ЕГЭ Физика · Механика","front":"Кинематика\nЗапиши перемещение s при постоянном ускорении a, начальной скорости v0 и времени t.","back":"Ответ: s=v0*t+a*t^2/2.\n\ns = v₀t + at²/2. Все величины здесь являются проекциями на выбранную ось; ускорение постоянно.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":1},"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","formula":"s=v0*t+a*t^2/2","formulaSide":"back","source":"Физика с котом: Кинематика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Кинематика"},{"id":"ege-physics-1-easy","topic":"ЕГЭ Физика · Механика","front":"Кинематика\nТело равномерно движется со скоростью 3 м/с в течение 2 с. Найди путь.","back":"Ответ: 6 м.\n\ns = vt = 3·2 = 6 м.","hints":["Раздел «Кинематика». Отделите искомую величину от данных условия. Ответ требуется в м.","Используйте связь s=v0*t+a*t^2/2. Выразите искомую величину до подстановки чисел. Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение."],"answerSpec":{"kind":"number","value":6,"unit":"м"},"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Кинематика"},{"id":"ege-physics-1-task","topic":"ЕГЭ Физика · Механика","front":"Кинематика\nТележка стартует из покоя с постоянным ускорением 2 м/с². Какой путь она пройдёт за 3 с?","back":"Ответ: 9 м.\n\ns = at²/2 = 2·9/2 = 9 м. Направление движения не меняется, поэтому путь равен модулю перемещения.\n\nv = at = 6 м/с. Средняя скорость (0 + 6)/2 = 3 м/с; s = 3·3 = 9 м.\n\nНа графике v(t) путь равен площади треугольника: 3·6/2 = 9 м.","hints":["Раздел «Кинематика». Отделите искомую величину от данных условия. Ответ требуется в м.","Используйте связь s=v0*t+a*t^2/2. Выразите искомую величину до подстановки чисел. Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение."],"answerSpec":{"kind":"number","value":9,"unit":"м"},"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Кинематика"},{"id":"ege-physics-1-bonus","topic":"ЕГЭ Физика · Механика","front":"Кинематика · Повышенная сложность\nТело движется прямолинейно со скоростью 12 м/с и тормозит с постоянным ускорением 3 м/с² по модулю. Найди путь до остановки.","back":"Ответ: 24 м.\n\n0 = v₀² - 2as, поэтому s = 144/6 = 24 м.\n\nt = 12/3 = 4 с; средняя скорость 6 м/с. Путь 6·4 = 24 м.","hints":["Раздел «Кинематика». Отделите искомую величину от данных условия. Ответ требуется в м.","Используйте связь s=v0*t+a*t^2/2. Выразите искомую величину до подстановки чисел. Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение."],"answerSpec":{"kind":"number","value":24,"unit":"м"},"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Кинематика"},{"id":"ege-physics-1-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Кинематика: объясни формулу s=v*t. Что означают величины и когда её применять?","back":"Эс равно вэ умножить на тэ.\n\ns: перемещение, м; v: постоянная скорость вдоль оси, м/с; t: время, с.\n\nПрименяется при постоянной скорости. Если тело не разворачивается, путь равен модулю перемещения.","formula":"s=v*t","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","objective":"Кинематика"},{"id":"ege-physics-1-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Кинематика: объясни формулу v=v0+a*t. Что означают величины и когда её применять?","back":"Вэ равно вэ нулевое плюс а умножить на тэ.\n\nv: конечная скорость; v₀: начальная скорость; a: постоянное ускорение, м/с²; t: время.\n\nУскорение 2 м/с² означает, что проекция скорости каждую секунду увеличивается на 2 м/с.","formula":"v=v0+a*t","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","objective":"Кинематика"},{"id":"ege-physics-1-meaning-2","topic":"ЕГЭ Физика · Механика","front":"Кинематика: объясни формулу s=v0*t+a*t^2/2. Что означают величины и когда её применять?","back":"Эс равно вэ нулевое тэ плюс а тэ в квадрате пополам.\n\ns: перемещение; v₀: начальная скорость; a: постоянное ускорение; t: время.\n\nПервое слагаемое описывает движение с начальной скоростью, второе прибавку перемещения из-за ускорения. Из покоя v₀ = 0.","formula":"s=v0*t+a*t^2/2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","objective":"Кинематика"},{"id":"ege-physics-1-meaning-3","topic":"ЕГЭ Физика · Механика","front":"Кинематика: объясни формулу a=(v-v0)/t. Что означают величины и когда её применять?","back":"А равно разности конечной и начальной скорости, делённой на время.\n\na: ускорение; v и v₀: скорости; t: длительность изменения.\n\nНа графике v(t) ускорение равно наклону прямой. Перемещение равно площади под графиком с учётом знака.","formula":"a=(v-v0)/t","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Для старта из покоя v₀ = 0. Площадь под графиком скорости даёт перемещение.","source":"Физика с котом: Кинематика","objective":"Кинематика"},{"id":"ege-physics-1-notes","topic":"ЕГЭ Физика · Механика","front":"Кинематика: какие условия применимости и типичные ошибки нужно помнить?","back":"v = v₀ + at; v² - v₀² = 2as. Наклон x(t) даёт v, наклон v(t) даёт a. При свободном падении a = g вниз. При броске под углом горизонтальная скорость постоянна, вертикальная меняется с ускорением g.","source":"Физика с котом: Кинематика","objective":"Кинематика"}]},{"id":"topic-2","name":"Силы и законы Ньютона","section":"Механика","cards":[{"id":"ege-physics-2-formula","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона\nЗапиши второй закон Ньютона: равнодействующая F, масса m, ускорение a.","back":"Ответ: F=m*a.\n\nВ инерциальной системе отсчёта векторная сумма сил F = ma. Сила и ускорение сонаправлены.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":2},"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","formula":"F=m*a","formulaSide":"back","source":"Физика с котом: Силы и законы Ньютона","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-easy","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона\nНа тело массой 2 кг действует равнодействующая 4 Н. Найди ускорение.","back":"Ответ: 2 м/с².\n\na = F/m = 4/2 = 2 м/с².","hints":["Раздел «Силы и законы Ньютона». Отделите искомую величину от данных условия. Ответ требуется в м/с².","Используйте связь F=m*a. Выразите искомую величину до подстановки чисел. Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма."],"answerSpec":{"kind":"number","value":2,"unit":"м/с²"},"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-task","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона\nБрусок массой 2 кг тянут вправо силой 10 Н. Сила трения равна 4 Н и направлена влево. Найди ускорение.","back":"Ответ: 3 м/с².\n\nРавнодействующая 10 - 4 = 6 Н вправо. a = F/m = 6/2 = 3 м/с² вправо.","hints":["Раздел «Силы и законы Ньютона». Отделите искомую величину от данных условия. Ответ требуется в м/с².","Используйте связь F=m*a. Выразите искомую величину до подстановки чисел. Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма."],"answerSpec":{"kind":"number","value":3,"unit":"м/с²"},"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-bonus","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона · Повышенная сложность\nБрусок скользит вниз по плоскости под углом 30° к горизонту. Коэффициент трения 0,2. Найди ускорение вниз вдоль плоскости. g = 10 м/с², cos 30° = 0,866.","back":"Ответ: 3.268 м/с².\n\nВдоль плоскости: ma = mg sin 30° - μN. Перпендикулярно: N = mg cos 30°.\n\na = g(sin 30° - μ cos 30°) = 10(0,5 - 0,2·0,866) = 3,268 м/с². Масса сокращается.","hints":["Раздел «Силы и законы Ньютона». Отделите искомую величину от данных условия. Ответ требуется в м/с².","Используйте связь F=m*a. Выразите искомую величину до подстановки чисел. Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма."],"answerSpec":{"kind":"number","value":3.268,"unit":"м/с²"},"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона: объясни формулу F=m*a. Что означают величины и когда её применять?","back":"Эф равно эм а.\n\nF: равнодействующая всех сил, Н; m: масса, кг; a: ускорение, м/с².\n\nВекторы равнодействующей и ускорения сонаправлены. Если сумма сил нулевая, скорость постоянна, а не обязательно равна нулю.","formula":"F=m*a","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона: объясни формулу Ftr=mu*N. Что означают величины и когда её применять?","back":"Эф трения равно мю эн.\n\nFтр: сила трения скольжения; μ (мю): коэффициент трения, без единицы; N (эн): сила нормальной реакции опоры, Н.\n\nμN означает произведение коэффициента трения и реакции опоры. N не всегда равно mg, например на наклонной плоскости.","formula":"Ftr=mu*N","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-meaning-2","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона: объясни формулу F=k*abs(x). Что означают величины и когда её применять?","back":"Эф равно ка умножить на модуль икс.\n\nF: модуль силы упругости; k: жёсткость пружины, Н/м; x: деформация, м; вертикальные черты означают модуль.\n\nСила упругости стремится вернуть пружину к недеформированному состоянию.","formula":"F=k*abs(x)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-meaning-3","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона: объясни формулу F=m*g. Что означают величины и когда её применять?","back":"Эф тяжести равно эм жэ.\n\nF: сила тяжести; m: масса; g (жэ): ускорение свободного падения.\n\nСила тяжести действует вниз. Вес есть сила, с которой тело действует на опору или подвес, это другая сила.","formula":"F=m*g","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала сложи силы с учётом направлений. В F = ma входит именно их сумма.","source":"Физика с котом: Силы и законы Ньютона","objective":"Силы и законы Ньютона"},{"id":"ege-physics-2-notes","topic":"ЕГЭ Физика · Механика","front":"Силы и законы Ньютона: какие условия применимости и типичные ошибки нужно помнить?","back":"Fупр = k|x|; Fтр ск = μN; трение покоя ≤ μN. Силы действия и противодействия приложены к разным телам. Вес есть сила действия тела на опору или подвес; при свободном падении вес равен нулю.","source":"Физика с котом: Силы и законы Ньютона","objective":"Силы и законы Ньютона"}]},{"id":"topic-3","name":"Гравитация и окружность","section":"Механика","cards":[{"id":"ege-physics-3-formula","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность\nЗапиши силу тяготения двух точечных масс m1 и m2 на расстоянии r. Постоянная G.","back":"Ответ: F=G*m1*m2/r^2.\n\nF = Gm₁m₂/r². Расстояние считают между центрами для сферически симметричных тел, находящихся снаружи друг друга.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":3},"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","formula":"F=G*m1*m2/r^2","formulaSide":"back","source":"Физика с котом: Гравитация и окружность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Гравитация и окружность"},{"id":"ege-physics-3-easy","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность\nРасстояние между двумя точечными массами увеличили в 2 раза. Во сколько раз уменьшилась сила тяготения?","back":"Ответ: 4 раза.\n\nF ∝ 1/r². При r₂ = 2r₁ сила F₂ = F₁/4.","hints":["Раздел «Гравитация и окружность». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь F=G*m1*m2/r^2. Выразите искомую величину до подстановки чисел. В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты."],"answerSpec":{"kind":"number","value":4,"unit":"раза"},"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Гравитация и окружность"},{"id":"ege-physics-3-task","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность\nСкорость равномерного движения по окружности 4 м/с, радиус 2 м. Найди центростремительное ускорение.","back":"Ответ: 8 м/с².\n\na = v²/r = 16/2 = 8 м/с². Оно направлено к центру.\n\nω = v/r = 2 рад/с; a = ω²r = 4·2 = 8 м/с².","hints":["Раздел «Гравитация и окружность». Отделите искомую величину от данных условия. Ответ требуется в м/с².","Используйте связь F=G*m1*m2/r^2. Выразите искомую величину до подстановки чисел. В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты."],"answerSpec":{"kind":"number","value":8,"unit":"м/с²"},"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Гравитация и окружность"},{"id":"ege-physics-3-bonus","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность · Повышенная сложность\nСпутник движется по круговой орбите радиуса r. Во сколько раз увеличится период на орбите радиуса 4r вокруг той же планеты?","back":"Ответ: 8 раз.\n\nGMm/r² = mv²/r, поэтому v = √(GM/r). T = 2πr/v = 2π√(r³/GM). Отношение периодов 4^(3/2) = 8.\n\nПо третьему закону Кеплера T² ∝ r³ для круговых орбит: T₂/T₁ = √64 = 8.","hints":["Раздел «Гравитация и окружность». Отделите искомую величину от данных условия. Ответ требуется в раз.","Используйте связь F=G*m1*m2/r^2. Выразите искомую величину до подстановки чисел. В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты."],"answerSpec":{"kind":"number","value":8,"unit":"раз"},"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Гравитация и окружность"},{"id":"ege-physics-3-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность: объясни формулу ac=v^2/r=omega^2*r. Что означают величины и когда её применять?","back":"А центростремительное равно вэ в квадрате делить на эр, или омега в квадрате умножить на эр.\n\naц: ускорение к центру, м/с²; v: скорость, м/с; r: радиус, м; ω (омега): угловая скорость, рад/с.\n\nВдвое большая скорость при том же радиусе требует вчетверо большего ускорения.","formula":"ac=v^2/r=omega^2*r","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","objective":"Гравитация и окружность"},{"id":"ege-physics-3-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность: объясни формулу v=2*pi*r/T. Что означают величины и когда её применять?","back":"Вэ равно два пи эр делить на тэ.\n\nπ (пи): число примерно 3,14; r: радиус; T: период, время одного оборота.\n\nЗа один оборот тело проходит длину окружности 2πr.","formula":"v=2*pi*r/T","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","objective":"Гравитация и окружность"},{"id":"ege-physics-3-meaning-2","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность: объясни формулу F=G*m1*m2/r^2. Что означают величины и когда её применять?","back":"Эф равно жэ большое эм один эм два делить на эр в квадрате.\n\nG: гравитационная постоянная; m₁ и m₂: массы; r: расстояние между центрами для сферических тел.\n\nНе путай G, постоянную тяготения, и g, ускорение свободного падения.","formula":"F=G*m1*m2/r^2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","objective":"Гравитация и окружность"},{"id":"ege-physics-3-meaning-3","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность: объясни формулу g=G*M/(R+h)^2. Что означают величины и когда её применять?","back":"Жэ на высоте аш равно жэ большое эм делить на сумму эр и аш в квадрате.\n\ng: ускорение на высоте h; G: гравитационная постоянная; M: масса планеты; R: радиус планеты; h: высота над поверхностью.\n\nВ закон тяготения входит расстояние от центра планеты: R + h.","formula":"g=G*M/(R+h)^2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","objective":"Гравитация и окружность"},{"id":"ege-physics-3-meaning-4","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность: объясни формулу v=sqrt(G*M/R). Что означают величины и когда её применять?","back":"Первая космическая скорость равна корню из жэ эм, делённого на эр.\n\nv: скорость круговой орбиты у поверхности без атмосферы; G: гравитационная постоянная; M: масса планеты; R: радиус планеты.\n\nГравитация обеспечивает нужное ускорение к центру: GMm/R² = mv²/R.","formula":"v=sqrt(G*M/R)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В законе тяготения расстояние стоит в квадрате. Для спутника отсчитывай его от центра планеты.","source":"Физика с котом: Гравитация и окружность","objective":"Гравитация и окружность"},{"id":"ege-physics-3-notes","topic":"ЕГЭ Физика · Механика","front":"Гравитация и окружность: какие условия применимости и типичные ошибки нужно помнить?","back":"aц = v²/r = ω²r; v = 2πr/T. g(h) = GM/(R+h)²; первая космическая скорость √(GM/R). Центростремительная сила не является новой силой: это равнодействующая реальных сил к центру.","source":"Физика с котом: Гравитация и окружность","objective":"Гравитация и окружность"}]},{"id":"topic-4","name":"Статика","section":"Механика","cards":[{"id":"ege-physics-4-formula","topic":"ЕГЭ Физика · Механика","front":"Статика\nЗапиши модуль момента силы F с плечом l.","back":"Ответ: M=F*l.\n\nM = Fl. Плечо есть кратчайшее расстояние от оси до линии действия силы, а не обязательно длина рычага.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":4},"hint":"Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться.","formula":"M=F*l","formulaSide":"back","source":"Физика с котом: Статика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Статика"},{"id":"ege-physics-4-easy","topic":"ЕГЭ Физика · Механика","front":"Статика\nСила 5 Н действует с плечом 2 м. Найди момент.","back":"Ответ: 10 Н·м.\n\nM = Fl = 5·2 = 10 Н·м.","hints":["Раздел «Статика». Отделите искомую величину от данных условия. Ответ требуется в Н·м.","Используйте связь M=F*l. Выразите искомую величину до подстановки чисел. Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться."],"answerSpec":{"kind":"number","value":10,"unit":"Н·м"},"hint":"Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться.","source":"Физика с котом: Статика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Статика"},{"id":"ege-physics-4-task","topic":"ЕГЭ Физика · Механика","front":"Статика\nНа левое плечо невесомого рычага 0,2 м действует сила 30 Н вниз. Какую силу вниз приложить к правому плечу 0,3 м для равновесия?","back":"Ответ: 20 Н.\n\nМоменты уравновешены: 30·0,2 = F·0,3. F = 20 Н.\n\nПлечо справа в 1,5 раза больше, поэтому сила в 1,5 раза меньше: 30/1,5 = 20 Н.","hints":["Раздел «Статика». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь M=F*l. Выразите искомую величину до подстановки чисел. Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться."],"answerSpec":{"kind":"number","value":20,"unit":"Н"},"hint":"Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться.","source":"Физика с котом: Статика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Статика"},{"id":"ege-physics-4-bonus","topic":"ЕГЭ Физика · Механика","front":"Статика · Повышенная сложность\nОднородная горизонтальная балка длиной 4 м и весом 100 Н опирается на концах. Груз весом 200 Н стоит в 1 м от левого конца. Найди реакцию правой опоры.","back":"Ответ: 100 Н.\n\nОтносительно левой опоры: Rправ·4 = 100·2 + 200·1, поэтому Rправ = 100 Н.\n\nРаспределение: вес балки даёт по 50 Н на опору. Груз даёт правой опоре 200·1/4 = 50 Н. Сумма 100 Н.","hints":["Раздел «Статика». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь M=F*l. Выразите искомую величину до подстановки чисел. Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться."],"answerSpec":{"kind":"number","value":100,"unit":"Н"},"hint":"Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться.","source":"Физика с котом: Статика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Статика"},{"id":"ege-physics-4-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Статика: объясни формулу M=F*l. Что означают величины и когда её применять?","back":"Эм равно эф эль.\n\nM: момент силы, Н·м; F: сила, Н; l: плечо, м, перпендикулярное расстояние от оси до линии действия силы.\n\nДлинная ручка ключа позволяет создать больший момент той же силой.","formula":"M=F*l","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться.","source":"Физика с котом: Статика","objective":"Статика"},{"id":"ege-physics-4-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Статика: объясни формулу F1*l1=F2*l2. Что означают величины и когда её применять?","back":"Эф один эль один равно эф два эль два.\n\nF₁, F₂: модули двух сил; l₁, l₂: их плечи.\n\nЭто равенство модулей противоположно направленных моментов. Оно не заменяет условие равенства нулю суммы сил.","formula":"F1*l1=F2*l2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Выбери ось. Моменты, вращающие тело в разные стороны, должны компенсироваться.","source":"Физика с котом: Статика","objective":"Статика"},{"id":"ege-physics-4-notes","topic":"ЕГЭ Физика · Механика","front":"Статика: какие условия применимости и типичные ошибки нужно помнить?","back":"Равновесие требует одновременно ΣF = 0 и ΣM = 0. Центр тяжести однородной балки находится посередине. Устойчивость связана с повышением центра масс при малом отклонении.","source":"Физика с котом: Статика","objective":"Статика"}]},{"id":"topic-5","name":"Жидкости и газы: давление","section":"Механика","cards":[{"id":"ege-physics-5-formula","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление\nЗапиши выталкивающую силу через плотность жидкости rho, g и погружённый объём V.","back":"Ответ: F=rho*g*V.\n\nFА = ρжgVпогр. Это вес вытесненной жидкости; плотность берут у жидкости, а не у тела.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":5},"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","formula":"F=rho*g*V","formulaSide":"back","source":"Физика с котом: Жидкости и газы: давление","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-easy","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление\nНайди избыточное давление воды на глубине 1 м: ρ = 1000 кг/м³, g = 10 м/с².","back":"Ответ: 10000 Па.\n\np = ρgh = 1000·10·1 = 10 000 Па.","hints":["Раздел «Жидкости и газы: давление». Отделите искомую величину от данных условия. Ответ требуется в Па.","Используйте связь F=rho*g*V. Выразите искомую величину до подстановки чисел. Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной."],"answerSpec":{"kind":"number","value":10000,"unit":"Па"},"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","source":"Физика с котом: Жидкости и газы: давление","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-task","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление\nТело вытеснило 0,002 м³ воды. Плотность воды 1000 кг/м³, g = 10 м/с². Найди силу Архимеда.","back":"Ответ: 20 Н.\n\nFА = 1000·10·0,002 = 20 Н.\n\nМасса вытесненной воды ρV = 2 кг; её вес 2·10 = 20 Н.","hints":["Раздел «Жидкости и газы: давление». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь F=rho*g*V. Выразите искомую величину до подстановки чисел. Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной."],"answerSpec":{"kind":"number","value":20,"unit":"Н"},"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","source":"Физика с котом: Жидкости и газы: давление","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-bonus","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление · Повышенная сложность\nДеревянный куб плотностью 600 кг/м³ плавает в воде плотностью 1000 кг/м³. Какая доля его объёма погружена? Ответ десятичной дробью.","back":"Ответ: 0.6.\n\nРавновесие: ρводыgVпогр = ρдерgV. Доля Vпогр/V = 600/1000 = 0,6.","hints":["Раздел «Жидкости и газы: давление». Отделите искомую величину от данных условия. ","Используйте связь F=rho*g*V. Выразите искомую величину до подстановки чисел. Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной."],"answerSpec":{"kind":"number","value":0.6,"unit":""},"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","source":"Физика с котом: Жидкости и газы: давление","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление: объясни формулу p=F/S. Что означают величины и когда её применять?","back":"Пэ равно эф делить на эс.\n\np: давление, Па; F: сила перпендикулярно поверхности, Н; S: площадь, м².\n\nНа большей площади одна и та же сила создаёт меньшее давление.","formula":"p=F/S","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","source":"Физика с котом: Жидкости и газы: давление","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление: объясни формулу p=rho*g*h. Что означают величины и когда её применять?","back":"Пэ равно ро жэ аш.\n\np: избыточное гидростатическое давление; ρ (ро): плотность жидкости; g: ускорение свободного падения; h: глубина.\n\nДля полного давления добавь давление на свободной поверхности.","formula":"p=rho*g*h","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","source":"Физика с котом: Жидкости и газы: давление","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-meaning-2","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление: объясни формулу Fa=rho*g*V. Что означают величины и когда её применять?","back":"Сила Архимеда равна ро жидкости жэ вэ погружённое.\n\nFА: выталкивающая сила; ρ: плотность жидкости; V: объём погружённой части тела.\n\nПлотность в этой формуле относится к жидкости, а не к телу.","formula":"Fa=rho*g*V","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сила Архимеда зависит от погружённого объёма. Давление растёт с глубиной.","source":"Физика с котом: Жидкости и газы: давление","objective":"Жидкости и газы: давление"},{"id":"ege-physics-5-notes","topic":"ЕГЭ Физика · Механика","front":"Жидкости и газы: давление: какие условия применимости и типичные ошибки нужно помнить?","back":"p = F/S; p = p₀ + ρgh; гидравлический пресс F₁/S₁ = F₂/S₂. Закон Паскаля: давление, приложенное к жидкости или газу, передаётся во все стороны.","source":"Физика с котом: Жидкости и газы: давление","objective":"Жидкости и газы: давление"}]},{"id":"topic-6","name":"Импульс","section":"Механика","cards":[{"id":"ege-physics-6-formula","topic":"ЕГЭ Физика · Механика","front":"Импульс\nЗапиши импульс тела p через массу m и скорость v.","back":"Ответ: p=m*v.\n\np = mv, вектор импульса сонаправлен скорости. Единица: кг·м/с.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":6},"hint":"Запиши сумму импульсов до и после, выбрав положительное направление.","formula":"p=m*v","formulaSide":"back","source":"Физика с котом: Импульс","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Импульс"},{"id":"ege-physics-6-easy","topic":"ЕГЭ Физика · Механика","front":"Импульс\nТело массой 3 кг движется со скоростью 2 м/с. Найди модуль импульса.","back":"Ответ: 6 кг·м/с.\n\np = mv = 3·2 = 6 кг·м/с.","hints":["Раздел «Импульс». Отделите искомую величину от данных условия. Ответ требуется в кг·м/с.","Используйте связь p=m*v. Выразите искомую величину до подстановки чисел. Запиши сумму импульсов до и после, выбрав положительное направление."],"answerSpec":{"kind":"number","value":6,"unit":"кг·м/с"},"hint":"Запиши сумму импульсов до и после, выбрав положительное направление.","source":"Физика с котом: Импульс","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Импульс"},{"id":"ege-physics-6-task","topic":"ЕГЭ Физика · Механика","front":"Импульс\nТележка 2 кг движется вправо со скоростью 3 м/с и сцепляется с неподвижной тележкой 1 кг. Внешним горизонтальным импульсом пренебречь. Найди общую скорость.","back":"Ответ: 2 м/с.\n\nСохраняется импульс: 2·3 + 1·0 = (2+1)v. v = 2 м/с вправо. Энергия при сцеплении не обязана сохраняться.","hints":["Раздел «Импульс». Отделите искомую величину от данных условия. Ответ требуется в м/с.","Используйте связь p=m*v. Выразите искомую величину до подстановки чисел. Запиши сумму импульсов до и после, выбрав положительное направление."],"answerSpec":{"kind":"number","value":2,"unit":"м/с"},"hint":"Запиши сумму импульсов до и после, выбрав положительное направление.","source":"Физика с котом: Импульс","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Импульс"},{"id":"ege-physics-6-bonus","topic":"ЕГЭ Физика · Механика","front":"Импульс · Повышенная сложность\nШар массой 0,2 кг летел вправо со скоростью 10 м/с и отскочил влево со скоростью 5 м/с. Найди модуль изменения импульса.","back":"Ответ: 3 кг·м/с.\n\nОсь вправо: Δp = 0,2·(-5) - 0,2·10 = -3 кг·м/с. Модуль 3.\n\nПри развороте векторы начального и конечного импульсов противоположны. Модуль их разности: 2 + 1 = 3 кг·м/с.","hints":["Раздел «Импульс». Отделите искомую величину от данных условия. Ответ требуется в кг·м/с.","Используйте связь p=m*v. Выразите искомую величину до подстановки чисел. Запиши сумму импульсов до и после, выбрав положительное направление."],"answerSpec":{"kind":"number","value":3,"unit":"кг·м/с"},"hint":"Запиши сумму импульсов до и после, выбрав положительное направление.","source":"Физика с котом: Импульс","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Импульс"},{"id":"ege-physics-6-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Импульс: объясни формулу p=m*v. Что означают величины и когда её применять?","back":"Пэ равно эм вэ.\n\np: импульс, кг·м/с; m: масса; v: скорость.\n\nПри изменении направления скорости меняется направление импульса.","formula":"p=m*v","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Запиши сумму импульсов до и после, выбрав положительное направление.","source":"Физика с котом: Импульс","objective":"Импульс"},{"id":"ege-physics-6-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Импульс: объясни формулу F*dt=m*(v-v0). Что означают величины и когда её применять?","back":"Импульс постоянной силы равен изменению импульса тела.\n\nF: равнодействующая; Δt: время действия; m: постоянная масса; v и v₀: конечная и начальная скорости вдоль оси.\n\nПри отскоке учитывай знак обеих скоростей.","formula":"F*dt=m*(v-v0)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Запиши сумму импульсов до и после, выбрав положительное направление.","source":"Физика с котом: Импульс","objective":"Импульс"},{"id":"ege-physics-6-notes","topic":"ЕГЭ Физика · Механика","front":"Импульс: какие условия применимости и типичные ошибки нужно помнить?","back":"Δp = FΔt для постоянной равнодействующей; площадь под F(t) даёт импульс силы. Σp сохраняется при нулевом внешнем импульсе. Реактивное движение объясняется тем же законом.","source":"Физика с котом: Импульс","objective":"Импульс"}]},{"id":"topic-7","name":"Работа, энергия, мощность","section":"Механика","cards":[{"id":"ege-physics-7-formula","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность\nЗапиши кинетическую энергию E тела массы m со скоростью v.","back":"Ответ: E=m*v^2/2.\n\nEк = mv²/2. Энергия скалярна и не зависит от направления скорости.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":7},"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","formula":"E=m*v^2/2","formulaSide":"back","source":"Физика с котом: Работа, энергия, мощность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-easy","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность\nСила 4 Н перемещает тело на 2 м в своём направлении. Найди работу.","back":"Ответ: 8 Дж.\n\nA = Fs = 4·2 = 8 Дж, угол между силой и перемещением равен нулю.","hints":["Раздел «Работа, энергия, мощность». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь E=m*v^2/2. Выразите искомую величину до подстановки чисел. Возведи скорость в квадрат, затем умножь на массу и раздели на два."],"answerSpec":{"kind":"number","value":8,"unit":"Дж"},"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-task","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность\nТело массой 2 кг движется со скоростью 3 м/с. Найди кинетическую энергию.","back":"Ответ: 9 Дж.\n\nEк = 2·3²/2 = 9 Дж.\n\nИмпульс p = 6 кг·м/с, Eк = p²/(2m) = 36/4 = 9 Дж.","hints":["Раздел «Работа, энергия, мощность». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь E=m*v^2/2. Выразите искомую величину до подстановки чисел. Возведи скорость в квадрат, затем умножь на массу и раздели на два."],"answerSpec":{"kind":"number","value":9,"unit":"Дж"},"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-bonus","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность · Повышенная сложность\nПружину жёсткостью 200 Н/м растянули от 0,10 до 0,20 м. Найди работу внешней силы при медленном растяжении без потерь.","back":"Ответ: 3 Дж.\n\nA = ΔEп = k(x₂² - x₁²)/2 = 100(0,04 - 0,01) = 3 Дж.\n\nСила линейно растёт от 20 до 40 Н. Средняя сила 30 Н, перемещение 0,1 м. Работа 3 Дж.","hints":["Раздел «Работа, энергия, мощность». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь E=m*v^2/2. Выразите искомую величину до подстановки чисел. Возведи скорость в квадрат, затем умножь на массу и раздели на два."],"answerSpec":{"kind":"number","value":3,"unit":"Дж"},"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-meaning-0","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность: объясни формулу E=m*v^2/2. Что означают величины и когда её применять?","back":"Кинетическая энергия равна эм вэ в квадрате пополам.\n\nE: кинетическая энергия, Дж; m: масса; v: модуль скорости.\n\nУдвоение скорости увеличивает энергию в четыре раза.","formula":"E=m*v^2/2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-meaning-1","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность: объясни формулу E=m*g*h. Что означают величины и когда её применять?","back":"Потенциальная энергия равна эм жэ аш.\n\nE: потенциальная энергия у поверхности Земли; h: высота над выбранным нулевым уровнем.\n\nНулевой уровень выбирают удобно; физически важна разность энергий.","formula":"E=m*g*h","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-meaning-2","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность: объясни формулу A=F*s*cos(alpha). Что означают величины и когда её применять?","back":"Работа равна эф эс косинус альфа.\n\nA: работа; F: постоянная сила; s: модуль перемещения; α (альфа): угол между силой и перемещением.\n\nПерпендикулярная перемещению сила работы не совершает.","formula":"A=F*s*cos(alpha)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-meaning-3","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность: объясни формулу P=A/t. Что означают величины и когда её применять?","back":"Мощность равна работе, делённой на время.\n\nP: средняя мощность, Вт; A: работа, Дж; t: время, с.\n\nКПД η (эта) равен отношению полезной энергии или работы к затраченной.","formula":"P=A/t","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Возведи скорость в квадрат, затем умножь на массу и раздели на два.","source":"Физика с котом: Работа, энергия, мощность","objective":"Работа, энергия, мощность"},{"id":"ege-physics-7-notes","topic":"ЕГЭ Физика · Механика","front":"Работа, энергия, мощность: какие условия применимости и типичные ошибки нужно помнить?","back":"A = Fs cos α; Aсум = ΔEк; Eп = mgh; Eпруж = kx²/2. При отсутствии потерь Eк + Eп = const. P = A/t; при сонаправленных F и v: P = Fv. КПД η = Aпол/Aзат.","source":"Физика с котом: Работа, энергия, мощность","objective":"Работа, энергия, мощность"}]},{"id":"topic-8","name":"Механические колебания","section":"Колебания и волны","cards":[{"id":"ege-physics-8-formula","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания\nЗапиши период T груза массы m на пружине жёсткости k. Используй pi и sqrt().","back":"Ответ: T=2*pi*sqrt(m/k).\n\nT = 2π√(m/k). Модель: лёгкая линейная пружина, груз, нет заметного затухания.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":8},"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","formula":"T=2*pi*sqrt(m/k)","formulaSide":"back","source":"Физика с котом: Механические колебания","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические колебания"},{"id":"ege-physics-8-easy","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания\nЗа 10 с маятник совершил 5 полных колебаний. Найди период.","back":"Ответ: 2 с.\n\nT = t/N = 10/5 = 2 с.","hints":["Раздел «Механические колебания». Отделите искомую величину от данных условия. Ответ требуется в с.","Используйте связь T=2*pi*sqrt(m/k). Выразите искомую величину до подстановки чисел. Период есть время одного полного колебания. У пружины T пропорционален корню из массы."],"answerSpec":{"kind":"number","value":2,"unit":"с"},"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические колебания"},{"id":"ege-physics-8-task","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания\nМассу пружинного маятника увеличили в 4 раза, жёсткость сохранили. Во сколько раз увеличился период?","back":"Ответ: 2 раза.\n\nT ∝ √m. Отношение периодов √4 = 2.","hints":["Раздел «Механические колебания». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь T=2*pi*sqrt(m/k). Выразите искомую величину до подстановки чисел. Период есть время одного полного колебания. У пружины T пропорционален корню из массы."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические колебания"},{"id":"ege-physics-8-bonus","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания · Повышенная сложность\nГруз на пружине имеет амплитуду 0,04 м и циклическую частоту 5 рад/с. Найди модуль скорости при смещении 0,024 м.","back":"Ответ: 0.16 м/с.\n\nv² = ω²(A² - x²). v = 5√(0,0016 - 0,000576) = 5·0,032 = 0,16 м/с.\n\nИз x = A cos φ получаем |cos φ| = 0,6, |sin φ| = 0,8. |v| = Aω|sin φ| = 0,04·5·0,8 = 0,16 м/с.","hints":["Раздел «Механические колебания». Отделите искомую величину от данных условия. Ответ требуется в м/с.","Используйте связь T=2*pi*sqrt(m/k). Выразите искомую величину до подстановки чисел. Период есть время одного полного колебания. У пружины T пропорционален корню из массы."],"answerSpec":{"kind":"number","value":0.16,"unit":"м/с"},"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические колебания"},{"id":"ege-physics-8-meaning-0","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания: объясни формулу T=2*pi*sqrt(m/k). Что означают величины и когда её применять?","back":"Тэ равно два пи корень из эм делить на ка.\n\nT: период; π (пи): число 3,14; m: масса груза; k: жёсткость пружины.\n\nТяжёлый груз на той же пружине колеблется медленнее.","formula":"T=2*pi*sqrt(m/k)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","objective":"Механические колебания"},{"id":"ege-physics-8-meaning-1","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания: объясни формулу T=2*pi*sqrt(l/g). Что означают величины и когда её применять?","back":"Период математического маятника равен два пи корень из эль делить на жэ.\n\nl: длина маятника; g: ускорение свободного падения.\n\nФормула приближённо верна при малых углах отклонения.","formula":"T=2*pi*sqrt(l/g)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","objective":"Механические колебания"},{"id":"ege-physics-8-meaning-2","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания: объясни формулу omega=2*pi/T. Что означают величины и когда её применять?","back":"Омега равно два пи делить на период.\n\nω (омега): циклическая частота, рад/с; T: период.\n\nОдна полная фаза колебания равна 2π радиан.","formula":"omega=2*pi/T","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","objective":"Механические колебания"},{"id":"ege-physics-8-meaning-3","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания: объясни формулу a=-omega^2*x. Что означают величины и когда её применять?","back":"Ускорение равно минус омега в квадрате икс.\n\na: проекция ускорения; x: смещение от равновесия; ω: циклическая частота.\n\nМинус означает, что ускорение направлено к равновесию.","formula":"a=-omega^2*x","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Период есть время одного полного колебания. У пружины T пропорционален корню из массы.","source":"Физика с котом: Механические колебания","objective":"Механические колебания"},{"id":"ege-physics-8-notes","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические колебания: какие условия применимости и типичные ошибки нужно помнить?","back":"x = A cos(ωt+φ); ω = 2π/T; a = -ω²x. Математический маятник: T = 2π√(l/g) при малых углах. Резонанс возникает при близости частоты воздействия к собственной частоте; затухание ограничивает амплитуду.","source":"Физика с котом: Механические колебания","objective":"Механические колебания"}]},{"id":"topic-9","name":"Механические волны и звук","section":"Колебания и волны","cards":[{"id":"ege-physics-9-formula","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук\nСвяжи скорость волны v, длину lambda и частоту f.","back":"Ответ: v=lambda*f.\n\nv = λf = λ/T. Частота показывает число колебаний за секунду, длина волны есть расстояние между ближайшими точками в одинаковой фазе.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":9},"hint":"Не путай скорость распространения волны со скоростью частиц среды.","formula":"v=lambda*f","formulaSide":"back","source":"Физика с котом: Механические волны и звук","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические волны и звук"},{"id":"ege-physics-9-easy","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук\nВолна длиной 3 м имеет частоту 2 Гц. Найди скорость.","back":"Ответ: 6 м/с.\n\nv = λf = 3·2 = 6 м/с.","hints":["Раздел «Механические волны и звук». Отделите искомую величину от данных условия. Ответ требуется в м/с.","Используйте связь v=lambda*f. Выразите искомую величину до подстановки чисел. Не путай скорость распространения волны со скоростью частиц среды."],"answerSpec":{"kind":"number","value":6,"unit":"м/с"},"hint":"Не путай скорость распространения волны со скоростью частиц среды.","source":"Физика с котом: Механические волны и звук","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические волны и звук"},{"id":"ege-physics-9-task","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук\nСкорость звука 340 м/с, частота 170 Гц. Найди длину волны.","back":"Ответ: 2 м.\n\nλ = v/f = 340/170 = 2 м.\n\nT = 1/170 с; за период волна проходит vT = 2 м.","hints":["Раздел «Механические волны и звук». Отделите искомую величину от данных условия. Ответ требуется в м.","Используйте связь v=lambda*f. Выразите искомую величину до подстановки чисел. Не путай скорость распространения волны со скоростью частиц среды."],"answerSpec":{"kind":"number","value":2,"unit":"м"},"hint":"Не путай скорость распространения волны со скоростью частиц среды.","source":"Физика с котом: Механические волны и звук","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические волны и звук"},{"id":"ege-physics-9-bonus","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук · Повышенная сложность\nСтруна длиной 0,75 м закреплена на обоих концах. Скорость волны 120 м/с. Найди частоту третьей гармоники.","back":"Ответ: 240 Гц.\n\nДля закреплённых концов L = nλ/2. λ₃ = 2·0,75/3 = 0,5 м. f₃ = 120/0,5 = 240 Гц.\n\nОсновная частота f₁ = v/(2L) = 80 Гц. f₃ = 3f₁ = 240 Гц.","hints":["Раздел «Механические волны и звук». Отделите искомую величину от данных условия. Ответ требуется в Гц.","Используйте связь v=lambda*f. Выразите искомую величину до подстановки чисел. Не путай скорость распространения волны со скоростью частиц среды."],"answerSpec":{"kind":"number","value":240,"unit":"Гц"},"hint":"Не путай скорость распространения волны со скоростью частиц среды.","source":"Физика с котом: Механические волны и звук","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Механические волны и звук"},{"id":"ege-physics-9-meaning-0","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук: объясни формулу v=lambda*f. Что означают величины и когда её применять?","back":"Вэ равно лямбда эф.\n\nv: скорость волны; λ (лямбда): длина волны; f: частота, Гц. Частоту также обозначают ν (ню).\n\nЗа один период волна проходит одну длину волны.","formula":"v=lambda*f","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Не путай скорость распространения волны со скоростью частиц среды.","source":"Физика с котом: Механические волны и звук","objective":"Механические волны и звук"},{"id":"ege-physics-9-meaning-1","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук: объясни формулу f=1/T. Что означают величины и когда её применять?","back":"Частота равна единице, делённой на период.\n\nf: частота; T: период.\n\nПри частоте 5 Гц за секунду происходит пять колебаний.","formula":"f=1/T","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Не путай скорость распространения волны со скоростью частиц среды.","source":"Физика с котом: Механические волны и звук","objective":"Механические волны и звук"},{"id":"ege-physics-9-notes","topic":"ЕГЭ Физика · Колебания и волны","front":"Механические волны и звук: какие условия применимости и типичные ошибки нужно помнить?","back":"В продольной волне частицы колеблются вдоль распространения, в поперечной поперёк. Звук в газе продольный и не идёт через вакуум. Высота звука связана с частотой, громкость также зависит от интенсивности. Для эха расстояние до преграды vt/2.","source":"Физика с котом: Механические волны и звук","objective":"Механические волны и звук"}]},{"id":"topic-10","name":"МКТ и температура","section":"Тепловая физика","cards":[{"id":"ege-physics-10-formula","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура\nЗапиши среднюю кинетическую энергию поступательного движения одной молекулы E через постоянную Больцмана k и температуру T.","back":"Ответ: E=3*k*T/2.\n\n⟨E⟩ = 3kT/2. Температура обязательно в кельвинах. Формула относится к поступательному движению молекулы идеального газа.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":10},"hint":"Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия.","formula":"E=3*k*T/2","formulaSide":"back","source":"Физика с котом: МКТ и температура","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"МКТ и температура"},{"id":"ege-physics-10-easy","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура\nПереведи 27 °C в кельвины. Используй T = t + 273.","back":"Ответ: 300 К.\n\nT = 27 + 273 = 300 К.","hints":["Раздел «МКТ и температура». Отделите искомую величину от данных условия. Ответ требуется в К.","Используйте связь E=3*k*T/2. Выразите искомую величину до подстановки чисел. Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия."],"answerSpec":{"kind":"number","value":300,"unit":"К"},"hint":"Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия.","source":"Физика с котом: МКТ и температура","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"МКТ и температура"},{"id":"ege-physics-10-task","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура\nТемпература газа выросла с 300 до 600 К. Во сколько раз выросла средняя энергия поступательного движения молекул?","back":"Ответ: 2 раза.\n\nE ∝ T. E₂/E₁ = 600/300 = 2.","hints":["Раздел «МКТ и температура». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь E=3*k*T/2. Выразите искомую величину до подстановки чисел. Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия.","source":"Физика с котом: МКТ и температура","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"МКТ и температура"},{"id":"ege-physics-10-bonus","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура · Повышенная сложность\nПри неизменной концентрации среднеквадратичная скорость молекул выросла в 3 раза. Во сколько раз выросло давление идеального газа?","back":"Ответ: 9 раз.\n\np = nm₀⟨v²⟩/3 = nm₀vср.кв²/3. При росте скорости в 3 раза квадрат растёт в 9 раз.\n\nT ∝ vср.кв², значит T увеличилась в 9 раз. При n = const давление p = nkT тоже выросло в 9 раз.","hints":["Раздел «МКТ и температура». Отделите искомую величину от данных условия. Ответ требуется в раз.","Используйте связь E=3*k*T/2. Выразите искомую величину до подстановки чисел. Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия."],"answerSpec":{"kind":"number","value":9,"unit":"раз"},"hint":"Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия.","source":"Физика с котом: МКТ и температура","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"МКТ и температура"},{"id":"ege-physics-10-meaning-0","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура: объясни формулу E=3*k*T/2. Что означают величины и когда её применять?","back":"Средняя энергия поступательного движения равна три вторых ка тэ.\n\nE: средняя энергия одной молекулы; k: постоянная Больцмана; T: абсолютная температура, К.\n\nЗдесь не учитывается энергия вращения и колебаний молекулы.","formula":"E=3*k*T/2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия.","source":"Физика с котом: МКТ и температура","objective":"МКТ и температура"},{"id":"ege-physics-10-meaning-1","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура: объясни формулу p=n*k*T. Что означают величины и когда её применять?","back":"Пэ равно эн ка тэ.\n\np: давление; n: концентрация, число частиц в 1 м³; k: постоянная Больцмана; T: температура.\n\nПри неизменной концентрации рост температуры повышает давление.","formula":"p=n*k*T","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сравнивай абсолютные температуры в кельвинах, а не числа в градусах Цельсия.","source":"Физика с котом: МКТ и температура","objective":"МКТ и температура"},{"id":"ege-physics-10-notes","topic":"ЕГЭ Физика · Тепловая физика","front":"МКТ и температура: какие условия применимости и типичные ошибки нужно помнить?","back":"p = nkT; p = nm₀⟨v²⟩/3; N = νNА; ν = m/M. Диффузия и броуновское движение свидетельствуют о тепловом движении частиц. Размер молекул не растёт при нагревании газа.","source":"Физика с котом: МКТ и температура","objective":"МКТ и температура"}]},{"id":"topic-11","name":"Газовые законы","section":"Тепловая физика","cards":[{"id":"ege-physics-11-formula","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы\nЗапиши уравнение состояния идеального газа через p, V, количество вещества nu, R и T.","back":"Ответ: p*V=nu*R*T.\n\npV = νRT. Для постоянного количества газа pV/T = const. Давление в Па, объём в м³, температура в К.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":11},"hint":"Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V.","formula":"p*V=nu*R*T","formulaSide":"back","source":"Физика с котом: Газовые законы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Газовые законы"},{"id":"ege-physics-11-easy","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы\nГаз при постоянной температуре и количестве вещества сжали вдвое. Во сколько раз выросло давление?","back":"Ответ: 2 раза.\n\npV = const. При уменьшении V вдвое p растёт вдвое.","hints":["Раздел «Газовые законы». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь p*V=nu*R*T. Выразите искомую величину до подстановки чисел. Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V.","source":"Физика с котом: Газовые законы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Газовые законы"},{"id":"ege-physics-11-task","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы\nГаз в закрытом жёстком сосуде нагрели с 300 до 450 К. Начальное давление 100 кПа. Найди конечное давление.","back":"Ответ: 150 кПа.\n\nV и ν постоянны, p/T = const. p₂ = 100·450/300 = 150 кПа.","hints":["Раздел «Газовые законы». Отделите искомую величину от данных условия. Ответ требуется в кПа.","Используйте связь p*V=nu*R*T. Выразите искомую величину до подстановки чисел. Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V."],"answerSpec":{"kind":"number","value":150,"unit":"кПа"},"hint":"Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V.","source":"Физика с котом: Газовые законы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Газовые законы"},{"id":"ege-physics-11-bonus","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы · Повышенная сложность\nКоличество газа неизменно. Давление увеличили в 3 раза, объём уменьшили в 2 раза. Было 200 К. Какой стала температура?","back":"Ответ: 300 К.\n\nT₂/T₁ = (p₂/p₁)(V₂/V₁) = 3/2. T₂ = 300 К.\n\nЗапиши p₁V₁ = νRT₁ и 3p₁·V₁/2 = νRT₂. Деление второго уравнения на первое даёт T₂ = 1,5T₁.","hints":["Раздел «Газовые законы». Отделите искомую величину от данных условия. Ответ требуется в К.","Используйте связь p*V=nu*R*T. Выразите искомую величину до подстановки чисел. Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V."],"answerSpec":{"kind":"number","value":300,"unit":"К"},"hint":"Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V.","source":"Физика с котом: Газовые законы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Газовые законы"},{"id":"ege-physics-11-meaning-0","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы: объясни формулу p*V=nu*R*T. Что означают величины и когда её применять?","back":"Пэ вэ равно ню эр тэ.\n\np: давление; V: объём; ν (ню): количество вещества, моль; R: универсальная газовая постоянная; T: температура в К.\n\nПри неизменном количестве вещества отношение pV/T постоянно.","formula":"p*V=nu*R*T","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V.","source":"Физика с котом: Газовые законы","objective":"Газовые законы"},{"id":"ege-physics-11-meaning-1","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы: объясни формулу p1*V1=p2*V2. Что означают величины и когда её применять?","back":"Пэ один вэ один равно пэ два вэ два.\n\nИндексы 1 и 2 обозначают начальное и конечное состояние. p: давление; V: объём.\n\nИзотермический процесс: количество газа и температура не меняются.","formula":"p1*V1=p2*V2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала определи, какая величина постоянна. В закрытом жёстком сосуде постоянны ν и V.","source":"Физика с котом: Газовые законы","objective":"Газовые законы"},{"id":"ege-physics-11-notes","topic":"ЕГЭ Физика · Тепловая физика","front":"Газовые законы: какие условия применимости и типичные ошибки нужно помнить?","back":"Изотерма: pV = const (гипербола на pV). Изобара: V/T = const. Изохора: p/T = const. Все три соотношения требуют неизменного количества газа.","source":"Физика с котом: Газовые законы","objective":"Газовые законы"}]},{"id":"topic-12","name":"Термодинамика","section":"Тепловая физика","cards":[{"id":"ege-physics-12-formula","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика\nЗапиши первое начало: полученное газом тепло Q, изменение внутренней энергии dU и работа газа A.","back":"Ответ: Q=dU+A.\n\nQ = ΔU + A, где A совершает сам газ. Если использовать работу внешних сил Aвнеш, тогда ΔU = Q + Aвнеш.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":12},"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","formula":"Q=dU+A","formulaSide":"back","source":"Физика с котом: Термодинамика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Термодинамика"},{"id":"ege-physics-12-easy","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика\nГаз нагревают в жёстком сосуде. Он получил 100 Дж теплоты. Найди изменение внутренней энергии.","back":"Ответ: 100 Дж.\n\nОбъём постоянен, A = 0. ΔU = Q = 100 Дж.","hints":["Раздел «Термодинамика». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь Q=dU+A. Выразите искомую величину до подстановки чисел. Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу."],"answerSpec":{"kind":"number","value":100,"unit":"Дж"},"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","source":"Физика с котом: Термодинамика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Термодинамика"},{"id":"ege-physics-12-task","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика\nГаз получил 500 Дж теплоты и совершил работу 200 Дж. Найди изменение внутренней энергии.","back":"Ответ: 300 Дж.\n\nΔU = Q - A = 500 - 200 = 300 Дж. Внутренняя энергия выросла.","hints":["Раздел «Термодинамика». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь Q=dU+A. Выразите искомую величину до подстановки чисел. Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу."],"answerSpec":{"kind":"number","value":300,"unit":"Дж"},"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","source":"Физика с котом: Термодинамика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Термодинамика"},{"id":"ege-physics-12-bonus","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика · Повышенная сложность\nИдеальная машина Карно работает между нагревателем 600 К и холодильником 300 К. За цикл получает 800 Дж. Найди работу за цикл.","back":"Ответ: 400 Дж.\n\nη = 1 - Tх/Tн = 1 - 300/600 = 0,5. A = ηQн = 400 Дж.\n\nДля цикла Карно Qх/Qн = Tх/Tн = 1/2. Qх = 400 Дж; A = Qн - Qх = 400 Дж.","hints":["Раздел «Термодинамика». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь Q=dU+A. Выразите искомую величину до подстановки чисел. Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу."],"answerSpec":{"kind":"number","value":400,"unit":"Дж"},"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","source":"Физика с котом: Термодинамика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Термодинамика"},{"id":"ege-physics-12-meaning-0","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика: объясни формулу Q=dU+A. Что означают величины и когда её применять?","back":"Ку равно дельта у плюс а.\n\nQ: полученная теплота; ΔU: изменение внутренней энергии; Δ (дельта): изменение величины; A: работа газа.\n\nПри сжатии работа самого газа отрицательна.","formula":"Q=dU+A","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","source":"Физика с котом: Термодинамика","objective":"Термодинамика"},{"id":"ege-physics-12-meaning-1","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика: объясни формулу A=p*dV. Что означают величины и когда её применять?","back":"А равно пэ дельта вэ.\n\np: постоянное давление; ΔV: изменение объёма.\n\nНа pV-графике работу показывает площадь под кривой с учётом направления процесса.","formula":"A=p*dV","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","source":"Физика с котом: Термодинамика","objective":"Термодинамика"},{"id":"ege-physics-12-meaning-2","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика: объясни формулу eta=1-Tx/Tn. Что означают величины и когда её применять?","back":"КПД Карно равно единица минус температура холодильника, делённая на температуру нагревателя.\n\nη (эта): КПД; Tх: температура холодильника; Tн: температура нагревателя, обе в К.\n\nЭто максимальный КПД между двумя резервуарами. Реальная машина обычно имеет меньший КПД.","formula":"eta=1-Tx/Tn","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Если газ расширяется, его работа положительна. Часть полученного тепла может уйти на работу.","source":"Физика с котом: Термодинамика","objective":"Термодинамика"},{"id":"ege-physics-12-notes","topic":"ЕГЭ Физика · Тепловая физика","front":"Термодинамика: какие условия применимости и типичные ошибки нужно помнить?","back":"Для одноатомного идеального газа U = 3νRT/2. Работа при постоянном p: A = pΔV; на pV-графике работа есть площадь под кривой с учётом знака. Изотермически ΔU = 0; адиабатически Q = 0. η = (Qн-Qх)/Qн ≤ 1-Tх/Tн.","source":"Физика с котом: Термодинамика","objective":"Термодинамика"}]},{"id":"topic-13","name":"Теплота и фазовые переходы","section":"Тепловая физика","cards":[{"id":"ege-physics-13-formula","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы\nЗапиши количество теплоты Q для нагрева массы m на dT при удельной теплоёмкости c.","back":"Ответ: Q=c*m*dT.\n\nQ = cmΔT без фазового перехода. Разность температур одинакова в К и °C. При охлаждении ΔT и полученное Q отрицательны.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":13},"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","formula":"Q=c*m*dT","formulaSide":"back","source":"Физика с котом: Теплота и фазовые переходы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-easy","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы\nПри плавлении 1 кг льда при 0 °C требуется 330 кДж. Сколько нужно для 0,1 кг при той же температуре?","back":"Ответ: 33 кДж.\n\nQ = λm = 330·0,1 = 33 кДж.","hints":["Раздел «Теплота и фазовые переходы». Отделите искомую величину от данных условия. Ответ требуется в кДж.","Используйте связь Q=c*m*dT. Выразите искомую величину до подстановки чисел. Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm."],"answerSpec":{"kind":"number","value":33,"unit":"кДж"},"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","source":"Физика с котом: Теплота и фазовые переходы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-task","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы\nНагрей 0,5 кг воды на 10 °C. c = 4200 Дж/(кг·К). Сколько теплоты нужно?","back":"Ответ: 21000 Дж.\n\nQ = 4200·0,5·10 = 21 000 Дж.\n\nТеплоёмкость порции C = cm = 2100 Дж/К. На 10 К нужно CΔT = 21 000 Дж.","hints":["Раздел «Теплота и фазовые переходы». Отделите искомую величину от данных условия. Ответ требуется в Дж.","Используйте связь Q=c*m*dT. Выразите искомую величину до подстановки чисел. Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm."],"answerSpec":{"kind":"number","value":21000,"unit":"Дж"},"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","source":"Физика с котом: Теплота и фазовые переходы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-bonus","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы · Повышенная сложность\nСмешали 0,2 кг воды при 80 °C и 0,3 кг воды при 20 °C. Теплоёмкостью сосуда и потерями пренебречь. Найди конечную температуру.","back":"Ответ: 44 °C.\n\n0,2c(80-t) = 0,3c(t-20). 16 - 0,2t = 0,3t - 6, поэтому t = 44 °C.\n\nДля одного вещества без переходов t = (m₁t₁ + m₂t₂)/(m₁+m₂) = (16+6)/0,5 = 44 °C.","hints":["Раздел «Теплота и фазовые переходы». Отделите искомую величину от данных условия. Ответ требуется в °C.","Используйте связь Q=c*m*dT. Выразите искомую величину до подстановки чисел. Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm."],"answerSpec":{"kind":"number","value":44,"unit":"°C"},"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","source":"Физика с котом: Теплота и фазовые переходы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-meaning-0","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы: объясни формулу Q=c*m*dT. Что означают величины и когда её применять?","back":"Ку равно цэ эм дельта тэ.\n\nQ: теплота; c: удельная теплоёмкость; m: масса; ΔT: изменение температуры.\n\nДля разности температур 1 К равен 1 °C.","formula":"Q=c*m*dT","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","source":"Физика с котом: Теплота и фазовые переходы","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-meaning-1","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы: объясни формулу Q=lambda*m. Что означают величины и когда её применять?","back":"Теплота плавления равна лямбда эм.\n\nλ (лямбда): удельная теплота плавления, Дж/кг; m: масса. Здесь λ не длина волны.\n\nФормула относится к веществу, уже достигшему температуры плавления.","formula":"Q=lambda*m","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","source":"Физика с котом: Теплота и фазовые переходы","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-meaning-2","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы: объясни формулу Q=L*m. Что означают величины и когда её применять?","back":"Теплота парообразования равна эль эм.\n\nL: удельная теплота парообразования; m: масса. Здесь L не индуктивность.\n\nПри конденсации такое же по модулю количество теплоты выделяется.","formula":"Q=L*m","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Если температура меняется, используй cmΔT. При плавлении при температуре плавления используй λm.","source":"Физика с котом: Теплота и фазовые переходы","objective":"Теплота и фазовые переходы"},{"id":"ege-physics-13-notes","topic":"ЕГЭ Физика · Тепловая физика","front":"Теплота и фазовые переходы: какие условия применимости и типичные ошибки нужно помнить?","back":"Плавление Q = λm; парообразование Q = Lm; сгорание Q = qm. При кристаллизации и конденсации теплота выделяется. В изолированной системе ΣQ = 0. Теплопередача: теплопроводность, конвекция, излучение.","source":"Физика с котом: Теплота и фазовые переходы","objective":"Теплота и фазовые переходы"}]},{"id":"topic-14","name":"Пар, жидкости и твёрдые тела","section":"Тепловая физика","cards":[{"id":"ege-physics-14-formula","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела\nЗапиши относительную влажность phi в процентах через давление пара p и насыщенного пара ps при той же температуре.","back":"Ответ: phi=p/ps*100.\n\nφ = (p/pнас)·100%. Давление насыщенного пара нужно брать при той же температуре. Также φ = ρ/ρнас·100% в приближении идеального пара.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":14},"hint":"Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах.","formula":"phi=p/ps*100","formulaSide":"back","source":"Физика с котом: Пар, жидкости и твёрдые тела","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Пар, жидкости и твёрдые тела"},{"id":"ege-physics-14-easy","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела\nДавление пара равно давлению насыщенного пара. Найди относительную влажность.","back":"Ответ: 100 %.\n\nφ = p/pнас·100% = 100%.","hints":["Раздел «Пар, жидкости и твёрдые тела». Отделите искомую величину от данных условия. Ответ требуется в %.","Используйте связь phi=p/ps*100. Выразите искомую величину до подстановки чисел. Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах."],"answerSpec":{"kind":"number","value":100,"unit":"%"},"hint":"Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах.","source":"Физика с котом: Пар, жидкости и твёрдые тела","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Пар, жидкости и твёрдые тела"},{"id":"ege-physics-14-task","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела\nДавление водяного пара 1,2 кПа, насыщенного при этой температуре 2 кПа. Найди относительную влажность.","back":"Ответ: 60 %.\n\nφ = 1,2/2·100% = 60%.","hints":["Раздел «Пар, жидкости и твёрдые тела». Отделите искомую величину от данных условия. Ответ требуется в %.","Используйте связь phi=p/ps*100. Выразите искомую величину до подстановки чисел. Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах."],"answerSpec":{"kind":"number","value":60,"unit":"%"},"hint":"Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах.","source":"Физика с котом: Пар, жидкости и твёрдые тела","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Пар, жидкости и твёрдые тела"},{"id":"ege-physics-14-bonus","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела · Повышенная сложность\nМыльная плёнка тянет подвижную проволоку длиной 0,1 м. Коэффициент поверхностного натяжения 0,03 Н/м. Плёнка имеет две поверхности. Найди силу.","back":"Ответ: 0.006 Н.\n\nКаждая поверхность даёт σl. F = 2σl = 2·0,03·0,1 = 0,006 Н.\n\nПри смещении на x площадь двух поверхностей растёт на 2lx. Работа Fx = σ·2lx, поэтому F = 2σl.","hints":["Раздел «Пар, жидкости и твёрдые тела». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь phi=p/ps*100. Выразите искомую величину до подстановки чисел. Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах."],"answerSpec":{"kind":"number","value":0.006,"unit":"Н"},"hint":"Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах.","source":"Физика с котом: Пар, жидкости и твёрдые тела","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Пар, жидкости и твёрдые тела"},{"id":"ege-physics-14-meaning-0","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела: объясни формулу phi=p/ps*100. Что означают величины и когда её применять?","back":"Фи равно пэ делить на давление насыщенного пара, умножить на сто процентов.\n\nφ (фи): относительная влажность, %; p: давление водяного пара; pнас: давление насыщенного пара при той же температуре.\n\nПри 100% пар насыщен. При охлаждении до точки росы начинается конденсация.","formula":"phi=p/ps*100","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах.","source":"Физика с котом: Пар, жидкости и твёрдые тела","objective":"Пар, жидкости и твёрдые тела"},{"id":"ege-physics-14-meaning-1","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела: объясни формулу F=2*sig*l. Что означают величины и когда её применять?","back":"Эф равно два сигма эль.\n\nσ (сигма маленькая): поверхностное натяжение, Н/м; l: длина подвижной стороны плёнки.\n\nДвойка возникает из-за двух поверхностей мыльной плёнки. Не путай σ с Σ, знаком суммы.","formula":"F=2*sig*l","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Влажность есть доля от насыщения. Значения давления должны быть в одинаковых единицах.","source":"Физика с котом: Пар, жидкости и твёрдые тела","objective":"Пар, жидкости и твёрдые тела"},{"id":"ege-physics-14-notes","topic":"ЕГЭ Физика · Тепловая физика","front":"Пар, жидкости и твёрдые тела: какие условия применимости и типичные ошибки нужно помнить?","back":"Точка росы: температура, при которой пар становится насыщенным при охлаждении. Fпов = σl для одной поверхности; капиллярность зависит от смачивания. Упругая деформация исчезает после снятия нагрузки, пластическая остаётся. Напряжение = F/S, относительное удлинение = Δl/l; закон Гука: F/S = E·Δl/l.","source":"Физика с котом: Пар, жидкости и твёрдые тела","objective":"Пар, жидкости и твёрдые тела"}]},{"id":"topic-15","name":"Электрическое поле","section":"Электричество","cards":[{"id":"ege-physics-15-formula","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле\nЗапиши модуль силы Кулона для зарядов q1, q2 на расстоянии r в вакууме. Постоянная k.","back":"Ответ: F=k*abs(q1*q2)/r^2.\n\nF = k|q₁q₂|/r². Здесь q₁ и q₂ можно понимать как модули зарядов. Одноимённые отталкиваются, разноимённые притягиваются.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":15},"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","formula":"F=k*abs(q1*q2)/r^2","formulaSide":"back","source":"Физика с котом: Электрическое поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электрическое поле"},{"id":"ege-physics-15-easy","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле\nНа заряд 2 Кл действует сила 6 Н. Найди напряжённость поля.","back":"Ответ: 3 Н/Кл.\n\nE = F/q = 6/2 = 3 Н/Кл.","hints":["Раздел «Электрическое поле». Отделите искомую величину от данных условия. Ответ требуется в Н/Кл.","Используйте связь F=k*abs(q1*q2)/r^2. Выразите искомую величину до подстановки чисел. Напряжённость показывает силу на единицу положительного пробного заряда."],"answerSpec":{"kind":"number","value":3,"unit":"Н/Кл"},"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","source":"Физика с котом: Электрическое поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электрическое поле"},{"id":"ege-physics-15-task","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле\nВ однородном поле 200 Н/Кл находится положительный заряд 0,01 Кл. Найди силу.","back":"Ответ: 2 Н.\n\nF = qE = 0,01·200 = 2 Н, по направлению поля.","hints":["Раздел «Электрическое поле». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь F=k*abs(q1*q2)/r^2. Выразите искомую величину до подстановки чисел. Напряжённость показывает силу на единицу положительного пробного заряда."],"answerSpec":{"kind":"number","value":2,"unit":"Н"},"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","source":"Физика с котом: Электрическое поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электрическое поле"},{"id":"ege-physics-15-bonus","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле · Повышенная сложность\nДва одинаковых положительных заряда создают в точке поля по 30 Н/Кл. Угол между векторами полей 120°. Найди модуль суммарной напряжённости.","back":"Ответ: 30 Н/Кл.\n\nПо правилу сложения векторов E² = E₁²+E₂²+2E₁E₂ cos120° = 900+900-900 = 900. E = 30 Н/Кл.\n\nПоперечные компоненты компенсируются, компоненты вдоль биссектрисы складываются: E = 2·30 cos60° = 30 Н/Кл.","hints":["Раздел «Электрическое поле». Отделите искомую величину от данных условия. Ответ требуется в Н/Кл.","Используйте связь F=k*abs(q1*q2)/r^2. Выразите искомую величину до подстановки чисел. Напряжённость показывает силу на единицу положительного пробного заряда."],"answerSpec":{"kind":"number","value":30,"unit":"Н/Кл"},"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","source":"Физика с котом: Электрическое поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электрическое поле"},{"id":"ege-physics-15-meaning-0","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле: объясни формулу F=k*abs(q1*q2)/r^2. Что означают величины и когда её применять?","back":"Сила Кулона равна ка модуль ку один ку два делить на эр в квадрате.\n\nk: электрическая постоянная пропорциональности; q₁, q₂: заряды; r: расстояние.\n\nФормула для точечных зарядов в вакууме. Одноимённые отталкиваются.","formula":"F=k*abs(q1*q2)/r^2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","source":"Физика с котом: Электрическое поле","objective":"Электрическое поле"},{"id":"ege-physics-15-meaning-1","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле: объясни формулу E=F/q. Что означают величины и когда её применять?","back":"Напряжённость равна силе на единицу положительного заряда.\n\nE: напряжённость, Н/Кл; F: сила; q: положительный пробный заряд.\n\nЗдесь E означает поле, а не энергию.","formula":"E=F/q","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","source":"Физика с котом: Электрическое поле","objective":"Электрическое поле"},{"id":"ege-physics-15-meaning-2","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле: объясни формулу E=U/d. Что означают величины и когда её применять?","back":"Е равно у делить на дэ.\n\nE: напряжённость однородного поля; U: напряжение; d: расстояние вдоль поля.\n\nДля поля между широкими параллельными пластинами вдали от краёв.","formula":"E=U/d","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Напряжённость показывает силу на единицу положительного пробного заряда.","source":"Физика с котом: Электрическое поле","objective":"Электрическое поле"},{"id":"ege-physics-15-notes","topic":"ЕГЭ Физика · Электричество","front":"Электрическое поле: какие условия применимости и типичные ошибки нужно помнить?","back":"E = F/q; Eточ = k|q|/r²; φ = kq/r; U = φ₁-φ₂; Aполя = qU; E = U/d для однородного поля. Поля складываются векторно, потенциалы алгебраически. Заряд сохраняется и кратен элементарному заряду.","source":"Физика с котом: Электрическое поле","objective":"Электрическое поле"}]},{"id":"topic-16","name":"Конденсаторы","section":"Электричество","cards":[{"id":"ege-physics-16-formula","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы\nЗапиши ёмкость C через модуль заряда одной обкладки q и напряжение U.","back":"Ответ: C=q/U.\n\nC = q/U. Ёмкость измеряется в фарадах, заряд в кулонах, напряжение в вольтах.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":16},"hint":"Микрофарады, умноженные на вольты, дают микрокулоны.","formula":"C=q/U","formulaSide":"back","source":"Физика с котом: Конденсаторы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Конденсаторы"},{"id":"ege-physics-16-easy","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы\nНа конденсаторе 6 Кл при напряжении 3 В. Найди ёмкость.","back":"Ответ: 2 Ф.\n\nC = q/U = 6/3 = 2 Ф.","hints":["Раздел «Конденсаторы». Отделите искомую величину от данных условия. Ответ требуется в Ф.","Используйте связь C=q/U. Выразите искомую величину до подстановки чисел. Микрофарады, умноженные на вольты, дают микрокулоны."],"answerSpec":{"kind":"number","value":2,"unit":"Ф"},"hint":"Микрофарады, умноженные на вольты, дают микрокулоны.","source":"Физика с котом: Конденсаторы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Конденсаторы"},{"id":"ege-physics-16-task","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы\nЁмкость 2 мкФ, напряжение 10 В. Найди заряд одной обкладки по модулю в мкКл.","back":"Ответ: 20 мкКл.\n\nq = CU = 2 мкФ·10 В = 20 мкКл.\n\nВ СИ: q = 2·10⁻⁶·10 = 2·10⁻⁵ Кл = 20 мкКл.","hints":["Раздел «Конденсаторы». Отделите искомую величину от данных условия. Ответ требуется в мкКл.","Используйте связь C=q/U. Выразите искомую величину до подстановки чисел. Микрофарады, умноженные на вольты, дают микрокулоны."],"answerSpec":{"kind":"number","value":20,"unit":"мкКл"},"hint":"Микрофарады, умноженные на вольты, дают микрокулоны.","source":"Физика с котом: Конденсаторы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Конденсаторы"},{"id":"ege-physics-16-bonus","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы · Повышенная сложность\nЗаряженный конденсатор отключили от источника. Расстояние между пластинами увеличили в 2 раза. Во сколько раз увеличилась энергия? Краевыми эффектами пренебречь.","back":"Ответ: 2 раза.\n\nq постоянно, C = εε₀S/d уменьшается вдвое. W = q²/(2C) увеличивается вдвое. Энергия поступает от работы при раздвижении пластин.\n\nU = q/C удваивается, q постоянно. W = qU/2 тоже удваивается.","hints":["Раздел «Конденсаторы». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь C=q/U. Выразите искомую величину до подстановки чисел. Микрофарады, умноженные на вольты, дают микрокулоны."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"Микрофарады, умноженные на вольты, дают микрокулоны.","source":"Физика с котом: Конденсаторы","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Конденсаторы"},{"id":"ege-physics-16-meaning-0","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы: объясни формулу C=q/U. Что означают величины и когда её применять?","back":"Цэ равно ку делить на у.\n\nC: ёмкость, Ф; q: заряд одной обкладки; U: напряжение.\n\nБольшая ёмкость означает больший заряд при том же напряжении.","formula":"C=q/U","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Микрофарады, умноженные на вольты, дают микрокулоны.","source":"Физика с котом: Конденсаторы","objective":"Конденсаторы"},{"id":"ege-physics-16-meaning-1","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы: объясни формулу W=C*U^2/2=q^2/(2*C). Что означают величины и когда её применять?","back":"Энергия равна цэ у в квадрате пополам, или ку в квадрате делить на два цэ.\n\nW: энергия, Дж; C: ёмкость; U: напряжение; q: заряд.\n\nВыбирай форму по тому, что известно и что постоянно.","formula":"W=C*U^2/2=q^2/(2*C)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Микрофарады, умноженные на вольты, дают микрокулоны.","source":"Физика с котом: Конденсаторы","objective":"Конденсаторы"},{"id":"ege-physics-16-notes","topic":"ЕГЭ Физика · Электричество","front":"Конденсаторы: какие условия применимости и типичные ошибки нужно помнить?","back":"Cпл = εε₀S/d. W = CU²/2 = q²/(2C) = qU/2. Параллельно C = ΣCᵢ; последовательно 1/C = Σ1/Cᵢ. Подключённый идеальный источник удерживает U, отключённый изолированный конденсатор сохраняет q.","source":"Физика с котом: Конденсаторы","objective":"Конденсаторы"}]},{"id":"topic-17","name":"Постоянный ток","section":"Электричество","cards":[{"id":"ege-physics-17-formula","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток\nЗапиши закон Ома для участка: ток I, напряжение U, сопротивление R.","back":"Ответ: I=U/R.\n\nI = U/R для омического участка. Сопротивление измеряют в омах.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":17},"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","formula":"I=U/R","formulaSide":"back","source":"Физика с котом: Постоянный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Постоянный ток"},{"id":"ege-physics-17-easy","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток\nТок 2 А проходит через сопротивление 3 Ом. Найди напряжение.","back":"Ответ: 6 В.\n\nU = IR = 2·3 = 6 В.","hints":["Раздел «Постоянный ток». Отделите искомую величину от данных условия. Ответ требуется в В.","Используйте связь I=U/R. Выразите искомую величину до подстановки чисел. При параллельном соединении одинаково напряжение. При последовательном одинаков ток."],"answerSpec":{"kind":"number","value":6,"unit":"В"},"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","source":"Физика с котом: Постоянный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Постоянный ток"},{"id":"ege-physics-17-task","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток\nНа резисторе 6 Ом поддерживают 12 В. Найди ток.","back":"Ответ: 2 А.\n\nI = U/R = 12/6 = 2 А.","hints":["Раздел «Постоянный ток». Отделите искомую величину от данных условия. Ответ требуется в А.","Используйте связь I=U/R. Выразите искомую величину до подстановки чисел. При параллельном соединении одинаково напряжение. При последовательном одинаков ток."],"answerSpec":{"kind":"number","value":2,"unit":"А"},"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","source":"Физика с котом: Постоянный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Постоянный ток"},{"id":"ege-physics-17-bonus","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток · Повышенная сложность\nРезисторы 6 Ом и 3 Ом подключены параллельно к 12 В. Найди суммарную мощность.","back":"Ответ: 72 Вт.\n\nRэкв = 6·3/(6+3) = 2 Ом. P = U²/Rэкв = 144/2 = 72 Вт.\n\nТоки 12/6 = 2 А и 12/3 = 4 А. Общий ток 6 А; P = UI = 72 Вт.\n\nP₁ = 144/6 = 24 Вт, P₂ = 144/3 = 48 Вт. Сумма 72 Вт.","hints":["Раздел «Постоянный ток». Отделите искомую величину от данных условия. Ответ требуется в Вт.","Используйте связь I=U/R. Выразите искомую величину до подстановки чисел. При параллельном соединении одинаково напряжение. При последовательном одинаков ток."],"answerSpec":{"kind":"number","value":72,"unit":"Вт"},"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","source":"Физика с котом: Постоянный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Постоянный ток"},{"id":"ege-physics-17-meaning-0","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток: объясни формулу I=U/R. Что означают величины и когда её применять?","back":"И равно у делить на эр.\n\nI: ток, А; U: напряжение, В; R: сопротивление, Ом.\n\nЗакон Ома применим к омическому участку при неизменных условиях.","formula":"I=U/R","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","source":"Физика с котом: Постоянный ток","objective":"Постоянный ток"},{"id":"ege-physics-17-meaning-1","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток: объясни формулу P=U*I=I^2*R=U^2/R. Что означают величины и когда её применять?","back":"Мощность равна у и, или и в квадрате эр, или у в квадрате делить на эр.\n\nP: мощность, Вт; I: ток; U: напряжение; R: сопротивление резистора.\n\nПоследние две формы получены подстановкой закона Ома.","formula":"P=U*I=I^2*R=U^2/R","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","source":"Физика с котом: Постоянный ток","objective":"Постоянный ток"},{"id":"ege-physics-17-meaning-2","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток: объясни формулу Q=I^2*R*t. Что означают величины и когда её применять?","back":"Ку равно и в квадрате эр тэ.\n\nQ: выделившаяся теплота; I: постоянный ток; R: сопротивление; t: время.\n\nЗакон Джоуля и Ленца для неизменных тока и сопротивления.","formula":"Q=I^2*R*t","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"При параллельном соединении одинаково напряжение. При последовательном одинаков ток.","source":"Физика с котом: Постоянный ток","objective":"Постоянный ток"},{"id":"ege-physics-17-notes","topic":"ЕГЭ Физика · Электричество","front":"Постоянный ток: какие условия применимости и типичные ошибки нужно помнить?","back":"I = Δq/Δt; R = ρl/S. Последовательно R = ΣRᵢ; параллельно 1/R = Σ1/Rᵢ. P = UI = I²R = U²/R; Q = I²Rt. Амперметр включают последовательно, вольтметр параллельно. В металлах носители тока электроны, в электролитах ионы, в газах ионы и электроны, в вакууме электроны эмиссии. В полупроводниках носители электроны и дырки; p-n-переход проводит ток преимущественно в одном направлении.","source":"Физика с котом: Постоянный ток","objective":"Постоянный ток"}]},{"id":"topic-18","name":"Источник и полная цепь","section":"Электричество","cards":[{"id":"ege-physics-18-formula","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь\nЗапиши ток полной цепи через ЭДС eps, внешнее сопротивление R и внутреннее r.","back":"Ответ: I=eps/(R+r).\n\nI = ε/(R+r). ЭДС есть работа сторонних сил на единицу заряда; внешнее и внутреннее сопротивления соединены последовательно.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":18},"hint":"В знаменателе суммируются сопротивления нагрузки и самого источника.","formula":"I=eps/(R+r)","formulaSide":"back","source":"Физика с котом: Источник и полная цепь","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Источник и полная цепь"},{"id":"ege-physics-18-easy","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь\nУ идеального источника ЭДС 6 В и r = 0. Подключили 3 Ом. Найди ток.","back":"Ответ: 2 А.\n\nI = ε/R = 6/3 = 2 А.","hints":["Раздел «Источник и полная цепь». Отделите искомую величину от данных условия. Ответ требуется в А.","Используйте связь I=eps/(R+r). Выразите искомую величину до подстановки чисел. В знаменателе суммируются сопротивления нагрузки и самого источника."],"answerSpec":{"kind":"number","value":2,"unit":"А"},"hint":"В знаменателе суммируются сопротивления нагрузки и самого источника.","source":"Физика с котом: Источник и полная цепь","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Источник и полная цепь"},{"id":"ege-physics-18-task","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь\nЭДС источника 12 В, внутреннее сопротивление 1 Ом, нагрузка 5 Ом. Найди ток.","back":"Ответ: 2 А.\n\nI = 12/(5+1) = 2 А.","hints":["Раздел «Источник и полная цепь». Отделите искомую величину от данных условия. Ответ требуется в А.","Используйте связь I=eps/(R+r). Выразите искомую величину до подстановки чисел. В знаменателе суммируются сопротивления нагрузки и самого источника."],"answerSpec":{"kind":"number","value":2,"unit":"А"},"hint":"В знаменателе суммируются сопротивления нагрузки и самого источника.","source":"Физика с котом: Источник и полная цепь","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Источник и полная цепь"},{"id":"ege-physics-18-bonus","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь · Повышенная сложность\nУ источника ЭДС 12 В, внутреннее сопротивление 2 Ом. Найди максимально возможную мощность на резистивной нагрузке.","back":"Ответ: 18 Вт.\n\nP = ε²R/(R+r)² максимальна при R = r. Pmax = ε²/(4r) = 144/8 = 18 Вт.\n\n(R+r)² ≥ 4Rr, поэтому P ≤ ε²/(4r). Равенство при R = r = 2 Ом; I = 3 А, P = I²R = 18 Вт.","hints":["Раздел «Источник и полная цепь». Отделите искомую величину от данных условия. Ответ требуется в Вт.","Используйте связь I=eps/(R+r). Выразите искомую величину до подстановки чисел. В знаменателе суммируются сопротивления нагрузки и самого источника."],"answerSpec":{"kind":"number","value":18,"unit":"Вт"},"hint":"В знаменателе суммируются сопротивления нагрузки и самого источника.","source":"Физика с котом: Источник и полная цепь","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Источник и полная цепь"},{"id":"ege-physics-18-meaning-0","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь: объясни формулу I=eps/(R+r). Что означают величины и когда её применять?","back":"И равно ЭДС делить на сумму эр большого и эр маленького.\n\nℰ: ЭДС, В; R: внешнее сопротивление; r: внутреннее сопротивление.\n\nR и r различаются. Их нельзя заменять одной буквой.","formula":"I=eps/(R+r)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В знаменателе суммируются сопротивления нагрузки и самого источника.","source":"Физика с котом: Источник и полная цепь","objective":"Источник и полная цепь"},{"id":"ege-physics-18-meaning-1","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь: объясни формулу U=eps-I*r. Что означают величины и когда её применять?","back":"Напряжение на клеммах равно ЭДС минус и эр маленькое.\n\nU: напряжение нагрузки; ℰ: ЭДС; I: ток; r: внутреннее сопротивление.\n\nФормула дана для источника, отдающего ток в нагрузку.","formula":"U=eps-I*r","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В знаменателе суммируются сопротивления нагрузки и самого источника.","source":"Физика с котом: Источник и полная цепь","objective":"Источник и полная цепь"},{"id":"ege-physics-18-notes","topic":"ЕГЭ Физика · Электричество","front":"Источник и полная цепь: какие условия применимости и типичные ошибки нужно помнить?","back":"Напряжение на клеммах при отдаче тока U = ε - Ir. Ток короткого замыкания ε/r при r > 0. КПД источника с резистивной нагрузкой R/(R+r); максимум мощности нагрузки и максимум КПД не совпадают.","source":"Физика с котом: Источник и полная цепь","objective":"Источник и полная цепь"}]},{"id":"topic-19","name":"Магнитное поле","section":"Электромагнетизм","cards":[{"id":"ege-physics-19-formula","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле\nЗапиши модуль магнитной силы на заряд q со скоростью v под углом alpha к B. Считай q модулем заряда.","back":"Ответ: F=q*v*B*sin(alpha).\n\nF = |q|vB sin α. Сила перпендикулярна скорости и магнитному полю; для отрицательного заряда направление противоположно правилу для положительного.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":19},"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","formula":"F=q*v*B*sin(alpha)","formulaSide":"back","source":"Физика с котом: Магнитное поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Магнитное поле"},{"id":"ege-physics-19-easy","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле\nЗаряд летит строго вдоль магнитного поля. Чему равна магнитная сила?","back":"Ответ: 0 Н.\n\nУгол α = 0, sin α = 0. Магнитная сила равна нулю.","hints":["Раздел «Магнитное поле». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь F=q*v*B*sin(alpha). Выразите искомую величину до подстановки чисел. В формуле силы есть синус угла. При перпендикулярном движении он равен единице."],"answerSpec":{"kind":"number","value":0,"unit":"Н"},"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Магнитное поле"},{"id":"ege-physics-19-task","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле\nПроводник длиной 0,5 м с током 2 А перпендикулярен полю 0,4 Тл. Найди силу Ампера.","back":"Ответ: 0.4 Н.\n\nF = BIl sin90° = 0,4·2·0,5 = 0,4 Н.","hints":["Раздел «Магнитное поле». Отделите искомую величину от данных условия. Ответ требуется в Н.","Используйте связь F=q*v*B*sin(alpha). Выразите искомую величину до подстановки чисел. В формуле силы есть синус угла. При перпендикулярном движении он равен единице."],"answerSpec":{"kind":"number","value":0.4,"unit":"Н"},"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Магнитное поле"},{"id":"ege-physics-19-bonus","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле · Повышенная сложность\nЧастица массой 0,002 кг и зарядом 0,1 Кл движется перпендикулярно полю 0,5 Тл со скоростью 5 м/с. Найди радиус круговой траектории.","back":"Ответ: 0.2 м.\n\nМагнитная сила даёт центростремительное ускорение: qvB = mv²/r. r = mv/(qB) = 0,002·5/(0,1·0,5) = 0,2 м.","hints":["Раздел «Магнитное поле». Отделите искомую величину от данных условия. Ответ требуется в м.","Используйте связь F=q*v*B*sin(alpha). Выразите искомую величину до подстановки чисел. В формуле силы есть синус угла. При перпендикулярном движении он равен единице."],"answerSpec":{"kind":"number","value":0.2,"unit":"м"},"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Магнитное поле"},{"id":"ege-physics-19-meaning-0","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле: объясни формулу Fa=I*B*l*sin(alpha). Что означают величины и когда её применять?","back":"Сила Ампера равна и бэ эль синус альфа.\n\nFА: сила Ампера; I: ток; B: магнитная индукция, Тл; l: длина прямого проводника в поле; α (альфа): угол между током и полем.\n\nПри параллельном направлении тока и поля сила равна нулю.","formula":"Fa=I*B*l*sin(alpha)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","objective":"Магнитное поле"},{"id":"ege-physics-19-meaning-1","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле: объясни формулу Fl=abs(q)*v*B*sin(alpha). Что означают величины и когда её применять?","back":"Сила Лоренца равна модулю ку вэ бэ синус альфа.\n\nFЛ: модуль магнитной силы; q: заряд, Кл; v: скорость; B: индукция; α: угол между скоростью и полем.\n\nСила перпендикулярна скорости и не меняет кинетическую энергию точечного заряда.","formula":"Fl=abs(q)*v*B*sin(alpha)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","objective":"Магнитное поле"},{"id":"ege-physics-19-meaning-2","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле: объясни формулу r=m*v/(abs(q)*B). Что означают величины и когда её применять?","back":"Радиус равен эм вэ делить на модуль ку бэ.\n\nr: радиус; m: масса; v: скорость; q: заряд; B: индукция.\n\nВерно, когда скорость перпендикулярна однородному полю и нет других существенных сил.","formula":"r=m*v/(abs(q)*B)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","objective":"Магнитное поле"},{"id":"ege-physics-19-meaning-3","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле: объясни формулу T=2*pi*m/(abs(q)*B). Что означают величины и когда её применять?","back":"Период равен два пи эм делить на модуль ку бэ.\n\nT: период обращения; π (пи): 3,14; m: масса; q: заряд; B: индукция.\n\nВ нерелятивистской модели период не зависит от скорости.","formula":"T=2*pi*m/(abs(q)*B)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле силы есть синус угла. При перпендикулярном движении он равен единице.","source":"Физика с котом: Магнитное поле","objective":"Магнитное поле"},{"id":"ege-physics-19-notes","topic":"ЕГЭ Физика · Электромагнетизм","front":"Магнитное поле: какие условия применимости и типичные ошибки нужно помнить?","back":"FАмпера = BIl sin α. Поле создают токи и движущиеся заряды. Линии B замкнуты. Магнитная сила Лоренца не совершает работы над точечным зарядом, меняя направление скорости.","source":"Физика с котом: Магнитное поле","objective":"Магнитное поле"}]},{"id":"topic-20","name":"Электромагнитная индукция","section":"Электромагнетизм","cards":[{"id":"ege-physics-20-formula","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция\nЗапиши модуль средней ЭДС катушки из N витков, если поток через один виток изменился по модулю на dPhi за dt.","back":"Ответ: eps=N*dPhi/dt.\n\n|εср| = N|ΔΦ|/Δt. Закон со знаком минус ε = -N dΦ/dt выражает правило Ленца.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":20},"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","formula":"eps=N*dPhi/dt","formulaSide":"back","source":"Физика с котом: Электромагнитная индукция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-easy","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция\nЧерез один виток поток изменился на 0,3 Вб за 1 с. Найди модуль средней ЭДС.","back":"Ответ: 0.3 В.\n\n|ε| = |ΔΦ|/Δt = 0,3/1 = 0,3 В.","hints":["Раздел «Электромагнитная индукция». Отделите искомую величину от данных условия. Ответ требуется в В.","Используйте связь eps=N*dPhi/dt. Выразите искомую величину до подстановки чисел. Ток индукции противодействует изменению магнитного потока, которое его вызвало."],"answerSpec":{"kind":"number","value":0.3,"unit":"В"},"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-task","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция\nПоток через один виток изменился на 0,02 Вб за 0,1 с. В катушке 10 витков. Найди модуль средней ЭДС.","back":"Ответ: 2 В.\n\n|ε| = N|ΔΦ|/Δt = 10·0,02/0,1 = 2 В.","hints":["Раздел «Электромагнитная индукция». Отделите искомую величину от данных условия. Ответ требуется в В.","Используйте связь eps=N*dPhi/dt. Выразите искомую величину до подстановки чисел. Ток индукции противодействует изменению магнитного потока, которое его вызвало."],"answerSpec":{"kind":"number","value":2,"unit":"В"},"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-bonus","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция · Повышенная сложность\nТок в катушке индуктивностью 0,4 Гн равномерно уменьшился с 5 А до 1 А за 0,02 с. Найди модуль ЭДС самоиндукции.","back":"Ответ: 80 В.\n\n|ε| = L|ΔI|/Δt = 0,4·4/0,02 = 80 В.","hints":["Раздел «Электромагнитная индукция». Отделите искомую величину от данных условия. Ответ требуется в В.","Используйте связь eps=N*dPhi/dt. Выразите искомую величину до подстановки чисел. Ток индукции противодействует изменению магнитного потока, которое его вызвало."],"answerSpec":{"kind":"number","value":80,"unit":"В"},"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-meaning-0","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: объясни формулу Phi=B*S*cos(alpha). Что означают величины и когда её применять?","back":"Фи большое равно бэ эс косинус альфа.\n\nΦ (фи большое): магнитный поток, Вб; B: индукция; S: площадь; α: угол между B и нормалью, перпендикуляром к плоскости.\n\nЕсли поле перпендикулярно плоскости, угол с нормалью нулевой и поток максимален.","formula":"Phi=B*S*cos(alpha)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-meaning-1","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: объясни формулу eps=-N*dPhi/dt. Что означают величины и когда её применять?","back":"ЭДС равно минус эн дельта фи делить на дельта тэ.\n\nℰ: средняя ЭДС индукции; N: число витков; ΔΦ: изменение потока через один виток; Δt: промежуток времени.\n\nФормула с конечными приращениями даёт среднюю ЭДС. Для мгновенной ЭДС используют производную.","formula":"eps=-N*dPhi/dt","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-meaning-2","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: объясни формулу eps=B*l*v. Что означают величины и когда её применять?","back":"ЭДС движущегося проводника равна бэ эль вэ.\n\nB: однородная индукция; l: длина проводника; v: скорость.\n\nЗдесь B, проводник и скорость взаимно перпендикулярны. Для иной геометрии нужно учитывать проекции.","formula":"eps=B*l*v","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-meaning-3","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: объясни формулу psi=N*Phi=L*I. Что означают величины и когда её применять?","back":"Пси равно эн фи и равно эль и.\n\nΨ (пси): потокосцепление; N: число витков; Φ: поток через один виток; L: индуктивность, Гн; I: ток.\n\nLI относится к потокосцеплению всей катушки. Поток одного витка равен LI/N при одинаковом потоке через витки.","formula":"psi=N*Phi=L*I","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-meaning-4","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: объясни формулу eps=-L*dI/dt. Что означают величины и когда её применять?","back":"ЭДС самоиндукции равно минус эль дельта и делить на дельта тэ.\n\nL: постоянная индуктивность; ΔI: изменение тока; Δt: время.\n\nСамоиндукция препятствует быстрому изменению тока.","formula":"eps=-L*dI/dt","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-meaning-5","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: объясни формулу W=L*I^2/2. Что означают величины и когда её применять?","back":"Энергия магнитного поля равна эль и в квадрате пополам.\n\nW: энергия, Дж; L: индуктивность; I: ток.\n\nЭнергия запасена в магнитном поле.","formula":"W=L*I^2/2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Ток индукции противодействует изменению магнитного потока, которое его вызвало.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"},{"id":"ege-physics-20-notes","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитная индукция: какие условия применимости и типичные ошибки нужно помнить?","back":"Φ = BS cos α, угол с нормалью. εсам = -L dI/dt; Wмаг = LI²/2. Замкнутое медное или алюминиевое кольцо отталкивается при приближении магнита и притягивается при удалении. При неподвижном магните установившегося индукционного тока нет. Разрез размыкает путь тока.","source":"Физика с котом: Электромагнитная индукция","objective":"Электромагнитная индукция"}]},{"id":"topic-21","name":"LC-контур и переменный ток","section":"Электромагнетизм","cards":[{"id":"ege-physics-21-formula","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток\nЗапиши формулу Томсона: период T идеального контура с индуктивностью L и ёмкостью C.","back":"Ответ: T=2*pi*sqrt(L*C).\n\nT = 2π√(LC), f = 1/(2π√(LC)). Это собственные колебания идеального контура без сопротивления.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":21},"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","formula":"T=2*pi*sqrt(L*C)","formulaSide":"back","source":"Физика с котом: LC-контур и переменный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-easy","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток\nЗа 0,01 с происходят 10 колебаний. Найди период.","back":"Ответ: 0.001 с.\n\nT = t/N = 0,01/10 = 0,001 с.","hints":["Раздел «LC-контур и переменный ток». Отделите искомую величину от данных условия. Ответ требуется в с.","Используйте связь T=2*pi*sqrt(L*C). Выразите искомую величину до подстановки чисел. В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза."],"answerSpec":{"kind":"number","value":0.001,"unit":"с"},"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-task","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток\nВ идеальном LC-контуре ёмкость увеличили в 9 раз при прежней L. Во сколько раз увеличился период?","back":"Ответ: 3 раза.\n\nT ∝ √C. T₂/T₁ = √9 = 3.","hints":["Раздел «LC-контур и переменный ток». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь T=2*pi*sqrt(L*C). Выразите искомую величину до подстановки чисел. В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза."],"answerSpec":{"kind":"number","value":3,"unit":"раза"},"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-bonus","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток · Повышенная сложность\nВ идеальном LC-контуре максимальный ток 4 А. Найди модуль тока, когда энергия электрического поля составляет 75% полной энергии.","back":"Ответ: 2 А.\n\nНа магнитное поле остаётся 25%. LI²/2 = 0,25·LImax²/2. |I| = 0,5Imax = 2 А.\n\nЕсли q/qmax = √0,75, то по синусоидальному закону (I/Imax)² + (q/qmax)² = 1. |I|/Imax = √0,25 = 0,5.","hints":["Раздел «LC-контур и переменный ток». Отделите искомую величину от данных условия. Ответ требуется в А.","Используйте связь T=2*pi*sqrt(L*C). Выразите искомую величину до подстановки чисел. В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза."],"answerSpec":{"kind":"number","value":2,"unit":"А"},"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-0","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу T=2*pi*sqrt(L*C). Что означают величины и когда её применять?","back":"Формула Томсона: тэ равно два пи корень из эль цэ.\n\nT: период; L: индуктивность, Гн; C: ёмкость, Ф; π (пи): 3,14.\n\nПри увеличении L или C в четыре раза период удваивается.","formula":"T=2*pi*sqrt(L*C)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-1","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу nu=1/T=1/(2*pi*sqrt(L*C)). Что означают величины и когда её применять?","back":"Ню равно единице на период.\n\nν (ню): частота, Гц; T: период; L: индуктивность; C: ёмкость.\n\nНе путай ν, частоту, с v, скоростью.","formula":"nu=1/T=1/(2*pi*sqrt(L*C))","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-2","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу omega0=1/sqrt(L*C). Что означают величины и когда её применять?","back":"Омега нулевое равно единице на корень из эль цэ.\n\nω₀ (омега нулевое): собственная циклическая частота, рад/с.\n\nОна в 2π раз больше обычной частоты в Гц.","formula":"omega0=1/sqrt(L*C)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-3","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу W=q^2/(2*C)+L*I^2/2. Что означают величины и когда её применять?","back":"Полная энергия равна ку в квадрате на два цэ плюс эль и в квадрате пополам.\n\nW: полная энергия; q: мгновенный заряд; C: ёмкость; L: индуктивность; I: мгновенный ток.\n\nВ идеальном контуре сумма постоянна.","formula":"W=q^2/(2*C)+L*I^2/2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-4","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу I=Imax/sqrt(2). Что означают величины и когда её применять?","back":"Действующий ток равен амплитуде, делённой на корень из двух.\n\nI: действующее значение; Imax: амплитуда синусоидального тока.\n\nДля напряжения аналогично: Uд = Umax/√2. Действующее значение даёт такое же тепловое действие, как постоянный ток.","formula":"I=Imax/sqrt(2)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-5","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу XL=omega*L. Что означают величины и когда её применять?","back":"Икс эль равно омега эль.\n\nXₗ: индуктивное сопротивление, Ом; ω: циклическая частота; L: индуктивность.\n\nС ростом частоты индуктивное сопротивление растёт.","formula":"XL=omega*L","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-6","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу XC=1/(omega*C). Что означают величины и когда её применять?","back":"Икс цэ равно единице на омега цэ.\n\nXс: ёмкостное сопротивление, Ом; ω: циклическая частота; C: ёмкость.\n\nС ростом частоты ёмкостное сопротивление уменьшается.","formula":"XC=1/(omega*C)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-meaning-7","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: объясни формулу U1/U2=N1/N2. Что означают величины и когда её применять?","back":"У один на у два равно эн один на эн два.\n\nU₁, U₂: напряжения обмоток; N₁, N₂: числа витков.\n\nДля идеального трансформатора также U₁I₁ = U₂I₂. Реальный трансформатор имеет потери.","formula":"U1/U2=N1/N2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле Томсона под корнем произведение L и C. Изменение под корнем в 9 раз даёт изменение периода в 3 раза.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"},{"id":"ege-physics-21-notes","topic":"ЕГЭ Физика · Электромагнетизм","front":"LC-контур и переменный ток: какие условия применимости и типичные ошибки нужно помнить?","back":"W = q²/(2C) + LI²/2 = const. Заряд и ток сдвинуты по фазе на π/2. Для синусоиды Uд = Umax/√2, Iд = Imax/√2. Идеальный трансформатор U₁/U₂ = N₁/N₂ и U₁I₁ = U₂I₂. Резонанс возможен при частоте воздействия, близкой к собственной.","source":"Физика с котом: LC-контур и переменный ток","objective":"LC-контур и переменный ток"}]},{"id":"topic-22","name":"Электромагнитные волны","section":"Электромагнетизм","cards":[{"id":"ege-physics-22-formula","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны\nСвяжи длину волны lambda и частоту f со скоростью света c в вакууме.","back":"Ответ: c=lambda*f.\n\nc = λf. В вакууме электромагнитные волны всех частот имеют одну и ту же скорость c.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":22},"hint":"Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты.","formula":"c=lambda*f","formulaSide":"back","source":"Физика с котом: Электромагнитные волны","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитные волны"},{"id":"ege-physics-22-easy","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны\nЧастоту электромагнитной волны в вакууме удвоили. Во сколько раз уменьшилась длина волны?","back":"Ответ: 2 раза.\n\nλ = c/f. Скорость c постоянна, длина волны уменьшится вдвое.","hints":["Раздел «Электромагнитные волны». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь c=lambda*f. Выразите искомую величину до подстановки чисел. Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты.","source":"Физика с котом: Электромагнитные волны","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитные волны"},{"id":"ege-physics-22-task","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны\nЧастота радиоволны 100 МГц. Скорость света 3·10⁸ м/с. Найди длину волны в вакууме.","back":"Ответ: 3 м.\n\n100 МГц = 10⁸ Гц. λ = c/f = 3·10⁸/10⁸ = 3 м.","hints":["Раздел «Электромагнитные волны». Отделите искомую величину от данных условия. Ответ требуется в м.","Используйте связь c=lambda*f. Выразите искомую величину до подстановки чисел. Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты."],"answerSpec":{"kind":"number","value":3,"unit":"м"},"hint":"Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты.","source":"Физика с котом: Электромагнитные волны","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитные волны"},{"id":"ege-physics-22-bonus","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны · Повышенная сложность\nЛинейно поляризованный свет интенсивности I₀ проходит идеальный анализатор под углом 60° к направлению поляризации. Какова доля I/I₀?","back":"Ответ: 0.25.\n\nПо закону Малюса I/I₀ = cos²60° = (1/2)² = 0,25. Это уже поляризованный входной свет, дополнительный множитель 1/2 не нужен.","hints":["Раздел «Электромагнитные волны». Отделите искомую величину от данных условия. ","Используйте связь c=lambda*f. Выразите искомую величину до подстановки чисел. Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты."],"answerSpec":{"kind":"number","value":0.25,"unit":""},"hint":"Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты.","source":"Физика с котом: Электромагнитные волны","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Электромагнитные волны"},{"id":"ege-physics-22-meaning-0","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны: объясни формулу c=1/sqrt(eps0*mu0). Что означают величины и когда её применять?","back":"Цэ равно единице на корень из эпсилон нулевое мю нулевое.\n\nc: скорость света в вакууме; ε₀ (эпсилон нулевое): электрическая постоянная; μ₀ (мю нулевое): магнитная постоянная.\n\nc приблизительно 3·10⁸ м/с.","formula":"c=1/sqrt(eps0*mu0)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты.","source":"Физика с котом: Электромагнитные волны","objective":"Электромагнитные волны"},{"id":"ege-physics-22-meaning-1","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны: объясни формулу lambda=c*T=c/nu. Что означают величины и когда её применять?","back":"Лямбда равно цэ тэ, или цэ делить на ню.\n\nλ: длина волны; c: скорость в вакууме; T: период; ν: частота.\n\nЧастоту также обозначают f. В среде вместо c используют скорость волны в этой среде.","formula":"lambda=c*T=c/nu","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Мегагерц равен миллиону герц. Вакуумная скорость не зависит от частоты.","source":"Физика с котом: Электромагнитные волны","objective":"Электромагнитные волны"},{"id":"ege-physics-22-notes","topic":"ЕГЭ Физика · Электромагнетизм","front":"Электромагнитные волны: какие условия применимости и типичные ошибки нужно помнить?","back":"По росту частоты: радио, микроволны, инфракрасное, видимое, ультрафиолет, рентген, гамма. Электромагнитные волны поперечны и не требуют среды. Поляризация связана с направлением колебаний электрического поля.","source":"Физика с котом: Электромагнитные волны","objective":"Электромагнитные волны"}]},{"id":"topic-23","name":"Геометрическая оптика","section":"Оптика","cards":[{"id":"ege-physics-23-formula","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика\nЗапиши формулу тонкой линзы: фокусное расстояние F, расстояние до предмета a, до действительного изображения b.","back":"Ответ: 1/F=1/a+1/b.\n\n1/F = 1/a + 1/b для собирающей линзы, действительного предмета и действительного изображения. В общей знаковой записи мнимым расстояниям приписывают минус.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":23},"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","formula":"1/F=1/a+1/b","formulaSide":"back","source":"Физика с котом: Геометрическая оптика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Геометрическая оптика"},{"id":"ege-physics-23-easy","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика\nФокус собирающей линзы 0,5 м. Найди оптическую силу.","back":"Ответ: 2 дптр.\n\nD = 1/F = 1/0,5 = 2 дптр. Фокус берут в метрах.","hints":["Раздел «Геометрическая оптика». Отделите искомую величину от данных условия. Ответ требуется в дптр.","Используйте связь 1/F=1/a+1/b. Выразите искомую величину до подстановки чисел. В формуле линзы складываются обратные расстояния. Не складывай сами расстояния."],"answerSpec":{"kind":"number","value":2,"unit":"дптр"},"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","source":"Физика с котом: Геометрическая оптика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Геометрическая оптика"},{"id":"ege-physics-23-task","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика\nПредмет стоит в 30 см перед собирающей линзой с фокусом 10 см. На каком расстоянии за линзой получится изображение?","back":"Ответ: 15 см.\n\n1/b = 1/10 - 1/30 = 2/30. b = 15 см. Изображение действительное, перевёрнутое, уменьшенное вдвое.\n\nb = aF/(a-F) = 30·10/20 = 15 см. Это алгебраически преобразованная формула линзы.","hints":["Раздел «Геометрическая оптика». Отделите искомую величину от данных условия. Ответ требуется в см.","Используйте связь 1/F=1/a+1/b. Выразите искомую величину до подстановки чисел. В формуле линзы складываются обратные расстояния. Не складывай сами расстояния."],"answerSpec":{"kind":"number","value":15,"unit":"см"},"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","source":"Физика с котом: Геометрическая оптика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Геометрическая оптика"},{"id":"ege-physics-23-bonus","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика · Повышенная сложность\nСвет идёт из стекла с n = 1,5 в воздух с n = 1. Найди синус предельного угла полного внутреннего отражения.","back":"Ответ: 0.6666666667.\n\nПри предельном угле преломлённый луч идёт вдоль границы: n₁ sin αкр = n₂·1. sin αкр = 1/1,5 = 2/3 ≈ 0,667.","hints":["Раздел «Геометрическая оптика». Отделите искомую величину от данных условия. ","Используйте связь 1/F=1/a+1/b. Выразите искомую величину до подстановки чисел. В формуле линзы складываются обратные расстояния. Не складывай сами расстояния."],"answerSpec":{"kind":"number","value":0.6666666667,"unit":""},"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","source":"Физика с котом: Геометрическая оптика","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Геометрическая оптика"},{"id":"ege-physics-23-meaning-0","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика: объясни формулу 1/F=1/a+1/b. Что означают величины и когда её применять?","back":"Единица на эф равна единице на а плюс единица на бэ.\n\nF: фокусное расстояние; a: расстояние до предмета; b: расстояние до изображения.\n\nДля собирающей линзы с действительным предметом и изображением все три расстояния положительны.","formula":"1/F=1/a+1/b","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","source":"Физика с котом: Геометрическая оптика","objective":"Геометрическая оптика"},{"id":"ege-physics-23-meaning-1","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика: объясни формулу n1*sin(alpha)=n2*sin(theta). Что означают величины и когда её применять?","back":"Эн один синус альфа равно эн два синус тэта.\n\nn₁, n₂: показатели преломления; α (альфа): угол падения; θ (тэта): угол преломления.\n\nПри переходе границы частота не меняется, скорость и длина волны могут измениться.","formula":"n1*sin(alpha)=n2*sin(theta)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","source":"Физика с котом: Геометрическая оптика","objective":"Геометрическая оптика"},{"id":"ege-physics-23-meaning-2","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика: объясни формулу n=c/v. Что означают величины и когда её применять?","back":"Показатель преломления равен скорости света в вакууме, делённой на скорость в среде.\n\nn: показатель преломления; c: скорость в вакууме; v: фазовая скорость в среде.\n\nДля школьной модели обычного стекла n больше единицы.","formula":"n=c/v","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В формуле линзы складываются обратные расстояния. Не складывай сами расстояния.","source":"Физика с котом: Геометрическая оптика","objective":"Геометрическая оптика"},{"id":"ege-physics-23-notes","topic":"ЕГЭ Физика · Оптика","front":"Геометрическая оптика: какие условия применимости и типичные ошибки нужно помнить?","back":"Угол отражения равен углу падения, оба от нормали. n₁ sin α = n₂ sin β; n = c/v. Частота на границе не меняется. Увеличение по модулю Γ = |b/a|. Близорукость корректируют рассеивающей линзой, дальнозоркость собирающей.","source":"Физика с котом: Геометрическая оптика","objective":"Геометрическая оптика"}]},{"id":"topic-24","name":"Интерференция","section":"Оптика","cards":[{"id":"ege-physics-24-formula","topic":"ЕГЭ Физика · Оптика","front":"Интерференция\nЗапиши условие максимума двух когерентных волн с одинаковой начальной фазой: разность хода delta, целое m и длина lambda.","back":"Ответ: delta=m*lambda.\n\nΔ = mλ. Для устойчивой картины нужна постоянная разность фаз. Условие дано для одинаковых начальных фаз и без дополнительных фазовых скачков.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":24},"hint":"Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн.","formula":"delta=m*lambda","formulaSide":"back","source":"Физика с котом: Интерференция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Интерференция"},{"id":"ege-physics-24-easy","topic":"ЕГЭ Физика · Оптика","front":"Интерференция\nДве одинаковые синфазные волны приходят с разностью хода 0. Во сколько раз результирующая амплитуда больше амплитуды одной?","back":"Ответ: 2 раза.\n\nАмплитуды складываются: A + A = 2A. Интенсивность при этом растёт в 4 раза относительно одной волны.","hints":["Раздел «Интерференция». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь delta=m*lambda. Выразите искомую величину до подстановки чисел. Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн.","source":"Физика с котом: Интерференция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Интерференция"},{"id":"ege-physics-24-task","topic":"ЕГЭ Физика · Оптика","front":"Интерференция\nРазность хода двух синфазных волн 1200 нм, длина волны 600 нм. Найди порядок максимума m.","back":"Ответ: 2.\n\nm = Δ/λ = 1200/600 = 2. Волны приходят в одинаковой фазе.","hints":["Раздел «Интерференция». Отделите искомую величину от данных условия. ","Используйте связь delta=m*lambda. Выразите искомую величину до подстановки чисел. Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн."],"answerSpec":{"kind":"number","value":2,"unit":""},"hint":"Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн.","source":"Физика с котом: Интерференция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Интерференция"},{"id":"ege-physics-24-bonus","topic":"ЕГЭ Физика · Оптика","front":"Интерференция · Повышенная сложность\nВ опыте Юнга расстояние между щелями 0,5 мм, до экрана 2 м, длина волны 500 нм. Найди расстояние между соседними светлыми полосами в мм. Углы малы.","back":"Ответ: 2 мм.\n\nΔx = λL/d = 500·10⁻⁹·2/(0,5·10⁻³) = 0,002 м = 2 мм.\n\nДля соседних максимумов разность хода отличается на λ. При малых углах Δ(хода) ≈ d·Δx/L. Отсюда Δx = λL/d = 2 мм.","hints":["Раздел «Интерференция». Отделите искомую величину от данных условия. Ответ требуется в мм.","Используйте связь delta=m*lambda. Выразите искомую величину до подстановки чисел. Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн."],"answerSpec":{"kind":"number","value":2,"unit":"мм"},"hint":"Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн.","source":"Физика с котом: Интерференция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Интерференция"},{"id":"ege-physics-24-meaning-0","topic":"ЕГЭ Физика · Оптика","front":"Интерференция: объясни формулу pathDelta=m*lambda. Что означают величины и когда её применять?","back":"Разность хода равна эм лямбда.\n\nΔ: разность хода; m: целый порядок; λ: длина волны.\n\nУсловие максимума при одинаковых начальных фазах и без дополнительных фазовых скачков.","formula":"pathDelta=m*lambda","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн.","source":"Физика с котом: Интерференция","objective":"Интерференция"},{"id":"ege-physics-24-meaning-1","topic":"ЕГЭ Физика · Оптика","front":"Интерференция: объясни формулу pathDelta=(m+0.5)*lambda. Что означают величины и когда её применять?","back":"Разность хода равна эм плюс одна вторая, умноженное на лямбда.\n\nm: целое число; λ: длина волны.\n\nУсловие минимума для тех же предположений. Две волны одинаковой амплитуды могут полностью погасить друг друга.","formula":"pathDelta=(m+0.5)*lambda","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Для максимума укладывается целое число длин волн, для минимума нечётное число полуволн.","source":"Физика с котом: Интерференция","objective":"Интерференция"},{"id":"ege-physics-24-notes","topic":"ЕГЭ Физика · Оптика","front":"Интерференция: какие условия применимости и типичные ошибки нужно помнить?","back":"Минимум: Δ = (m+1/2)λ для синфазных источников. Две независимые обычные лампы не дают устойчивых полос. В тонких плёнках учитывается фазовый скачок при отражении; простое условие Δ = mλ без него может быть неприменимо.","source":"Физика с котом: Интерференция","objective":"Интерференция"}]},{"id":"topic-25","name":"Дифракция","section":"Оптика","cards":[{"id":"ege-physics-25-formula","topic":"ЕГЭ Физика · Оптика","front":"Дифракция\nЗапиши условие главного максимума решётки при нормальном падении: период d, угол theta, порядок m, длина lambda.","back":"Ответ: d*sin(theta)=m*lambda.\n\nd sin θ = mλ. d есть период решётки, а не ширина отдельной щели. Формула дана для нормального падения.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":25},"hint":"Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1.","formula":"d*sin(theta)=m*lambda","formulaSide":"back","source":"Физика с котом: Дифракция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Дифракция"},{"id":"ege-physics-25-easy","topic":"ЕГЭ Физика · Оптика","front":"Дифракция\nНа участке решётки длиной 1 мм расположено 100 периодов. Найди период в мкм.","back":"Ответ: 10 мкм.\n\nd = 1 мм/100 = 0,01 мм = 10 мкм.","hints":["Раздел «Дифракция». Отделите искомую величину от данных условия. Ответ требуется в мкм.","Используйте связь d*sin(theta)=m*lambda. Выразите искомую величину до подстановки чисел. Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1."],"answerSpec":{"kind":"number","value":10,"unit":"мкм"},"hint":"Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1.","source":"Физика с котом: Дифракция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Дифракция"},{"id":"ege-physics-25-task","topic":"ЕГЭ Физика · Оптика","front":"Дифракция\nПериод решётки 2 мкм, длина волны 0,5 мкм. Найди sin θ для максимума первого порядка.","back":"Ответ: 0.25.\n\nsin θ = mλ/d = 1·0,5/2 = 0,25.","hints":["Раздел «Дифракция». Отделите искомую величину от данных условия. ","Используйте связь d*sin(theta)=m*lambda. Выразите искомую величину до подстановки чисел. Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1."],"answerSpec":{"kind":"number","value":0.25,"unit":""},"hint":"Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1.","source":"Физика с котом: Дифракция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Дифракция"},{"id":"ege-physics-25-bonus","topic":"ЕГЭ Физика · Оптика","front":"Дифракция · Повышенная сложность\nРешётка с периодом 2 мкм освещена нормально светом 0,6 мкм. Найди наибольший возможный целый порядок главного максимума.","back":"Ответ: 3.\n\n|sin θ| ≤ 1, значит |m| ≤ d/λ = 2/0,6 ≈ 3,33. Наибольшее целое m = 3.","hints":["Раздел «Дифракция». Отделите искомую величину от данных условия. ","Используйте связь d*sin(theta)=m*lambda. Выразите искомую величину до подстановки чисел. Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1."],"answerSpec":{"kind":"number","value":3,"unit":""},"hint":"Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1.","source":"Физика с котом: Дифракция","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Дифракция"},{"id":"ege-physics-25-meaning-0","topic":"ЕГЭ Физика · Оптика","front":"Дифракция: объясни формулу d*sin(theta)=m*lambda. Что означают величины и когда её применять?","back":"Дэ синус тэта равно эм лямбда.\n\nd: период решётки; θ: угол наблюдения от нормали; m: порядок максимума; λ: длина волны.\n\nФормула дана для нормального падения. Период решётки не равен ширине щели в общем случае.","formula":"d*sin(theta)=m*lambda","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1.","source":"Физика с котом: Дифракция","objective":"Дифракция"},{"id":"ege-physics-25-meaning-1","topic":"ЕГЭ Физика · Оптика","front":"Дифракция: объясни формулу sin(theta)=m*lambda/d. Что означают величины и когда её применять?","back":"Синус тэта равен эм лямбда делить на дэ.\n\nВсе длины надо выразить в одинаковых единицах.\n\nСинус не может быть больше 1. Это ограничивает максимальный порядок.","formula":"sin(theta)=m*lambda/d","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала переведи период и длину волны в одинаковые единицы. Синус не может быть больше 1.","source":"Физика с котом: Дифракция","objective":"Дифракция"},{"id":"ege-physics-25-notes","topic":"ЕГЭ Физика · Оптика","front":"Дифракция: какие условия применимости и типичные ошибки нужно помнить?","back":"Дифракция заметна при размерах отверстия или препятствия, сравнимых с длиной волны. Для одной щели ширины a минимумы: a sin θ = mλ, m ≠ 0. Не путай минимумы одной щели с максимумами решётки.","source":"Физика с котом: Дифракция","objective":"Дифракция"}]},{"id":"topic-26","name":"Фотоны, атом и фотоэффект","section":"Квантовая физика","cards":[{"id":"ege-physics-26-formula","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект\nЗапиши уравнение фотоэффекта: энергия фотона h*f, работа выхода A и максимальная кинетическая энергия K.","back":"Ответ: h*f=A+K.\n\nhf = Aвых + Kmax. Фотоэлектрон тратит часть энергии фотона на выход из вещества; остаток становится его кинетической энергией.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":26},"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","formula":"h*f=A+K","formulaSide":"back","source":"Физика с котом: Фотоны, атом и фотоэффект","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-easy","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект\nАтом перешёл с уровня 5 эВ на уровень 2 эВ, испустив фотон. Найди энергию фотона.","back":"Ответ: 3 эВ.\n\nEф = Eверх - Eниз = 5 - 2 = 3 эВ. Абсолютный ноль уровней здесь не важен.","hints":["Раздел «Фотоны, атом и фотоэффект». Отделите искомую величину от данных условия. Ответ требуется в эВ.","Используйте связь h*f=A+K. Выразите искомую величину до подстановки чисел. Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет."],"answerSpec":{"kind":"number","value":3,"unit":"эВ"},"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","source":"Физика с котом: Фотоны, атом и фотоэффект","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-task","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект\nЭнергия фотона 5 эВ, работа выхода 2 эВ. Найди максимальную кинетическую энергию фотоэлектрона.","back":"Ответ: 3 эВ.\n\nKmax = Eф - Aвых = 5 - 2 = 3 эВ.","hints":["Раздел «Фотоны, атом и фотоэффект». Отделите искомую величину от данных условия. Ответ требуется в эВ.","Используйте связь h*f=A+K. Выразите искомую величину до подстановки чисел. Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет."],"answerSpec":{"kind":"number","value":3,"unit":"эВ"},"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","source":"Физика с котом: Фотоны, атом и фотоэффект","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-bonus","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект · Повышенная сложность\nРабота выхода 2 эВ. Найди красную границу фотоэффекта в нм. Используй hc = 1240 эВ·нм.","back":"Ответ: 620 нм.\n\nНа пороге Kmax = 0, hc/λкр = Aвых. λкр = 1240/2 = 620 нм. Фотоэффект возможен при λ ≤ 620 нм.","hints":["Раздел «Фотоны, атом и фотоэффект». Отделите искомую величину от данных условия. Ответ требуется в нм.","Используйте связь h*f=A+K. Выразите искомую величину до подстановки чисел. Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет."],"answerSpec":{"kind":"number","value":620,"unit":"нм"},"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","source":"Физика с котом: Фотоны, атом и фотоэффект","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-meaning-0","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект: объясни формулу h*f=A+K. Что означают величины и когда её применять?","back":"Аш эф равно работе выхода плюс максимальная кинетическая энергия.\n\nh: постоянная Планка; f: частота; A: работа выхода; K: максимальная кинетическая энергия фотоэлектрона.\n\nЕсли hf меньше работы выхода, фотоэффекта в этой модели не будет.","formula":"h*f=A+K","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","source":"Физика с котом: Фотоны, атом и фотоэффект","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-meaning-1","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект: объясни формулу E=h*f=h*c/lambda. Что означают величины и когда её применять?","back":"Энергия фотона равна аш эф, или аш цэ делить на лямбда.\n\nE: энергия фотона; h: постоянная Планка; c: скорость света; λ: длина волны.\n\nПовышение частоты повышает энергию одного фотона.","formula":"E=h*f=h*c/lambda","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","source":"Физика с котом: Фотоны, атом и фотоэффект","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-meaning-2","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект: объясни формулу h*f=E2-E1. Что означают величины и когда её применять?","back":"Энергия фотона равна разности верхнего и нижнего уровней атома.\n\nE₂ и E₁: энергии уровней; E₂ > E₁.\n\nПереход вниз сопровождается испусканием фотона, вверх требует поглощения энергии.","formula":"h*f=E2-E1","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Энергия фотона сначала покрывает работу выхода. Если её недостаточно, фотоэффекта не будет.","source":"Физика с котом: Фотоны, атом и фотоэффект","objective":"Фотоны, атом и фотоэффект"},{"id":"ege-physics-26-notes","topic":"ЕГЭ Физика · Квантовая физика","front":"Фотоны, атом и фотоэффект: какие условия применимости и типичные ошибки нужно помнить?","back":"Eф = hf = hc/λ; pф = h/λ. Kmax = eUзад. Увеличение интенсивности при той же частоте не повышает Kmax, но может увеличить фототок. Атом испускает и поглощает фотоны с энергией разности уровней; линейчатые спектры отражают дискретность уровней.","source":"Физика с котом: Фотоны, атом и фотоэффект","objective":"Фотоны, атом и фотоэффект"}]},{"id":"topic-27","name":"Ядро и радиоактивность","section":"Квантовая физика","cards":[{"id":"ege-physics-27-formula","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность\nЗапиши число оставшихся ядер N через исходное N0, время t и период полураспада T.","back":"Ответ: N=N0*2^(-t/T).\n\nN = N₀·2^(-t/T). Это статистический закон для большого числа ядер. За каждый период остаётся половина ещё не распавшихся ядер.","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":27},"hint":"Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество.","formula":"N=N0*2^(-t/T)","formulaSide":"back","source":"Физика с котом: Ядро и радиоактивность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Ядро и радиоактивность"},{"id":"ege-physics-27-easy","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность\nВ ядре массовое число A = 14, зарядовое Z = 6. Сколько нейтронов?","back":"Ответ: 8.\n\nЧисло нейтронов A - Z = 14 - 6 = 8. Протонов 6.","hints":["Раздел «Ядро и радиоактивность». Отделите искомую величину от данных условия. ","Используйте связь N=N0*2^(-t/T). Выразите искомую величину до подстановки чисел. Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество."],"answerSpec":{"kind":"number","value":8,"unit":""},"hint":"Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество.","source":"Физика с котом: Ядро и радиоактивность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Ядро и радиоактивность"},{"id":"ege-physics-27-task","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность\nПериод полураспада 2 часа. Вначале было 8000 ядер. Сколько в среднем останется через 6 часов?","back":"Ответ: 1000 ядер.\n\nПрошло 6/2 = 3 периода. N = 8000/2³ = 1000.\n\nПоследовательно: 8000 → 4000 → 2000 → 1000.","hints":["Раздел «Ядро и радиоактивность». Отделите искомую величину от данных условия. Ответ требуется в ядер.","Используйте связь N=N0*2^(-t/T). Выразите искомую величину до подстановки чисел. Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество."],"answerSpec":{"kind":"number","value":1000,"unit":"ядер"},"hint":"Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество.","source":"Физика с котом: Ядро и радиоактивность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Ядро и радиоактивность"},{"id":"ege-physics-27-bonus","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность · Повышенная сложность\nЯдро с A = 238, Z = 92 испытало один α-распад и два β⁻-распада. Найди итоговое зарядовое число Z.","back":"Ответ: 92.\n\nПосле α: A = 234, Z = 90. Каждый β⁻ увеличивает Z на 1, не меняя A. Итог: A = 234, Z = 92.\n\nСуммарное изменение Z: -2 + 1 + 1 = 0. Поэтому Zкон = 92.","hints":["Раздел «Ядро и радиоактивность». Отделите искомую величину от данных условия. ","Используйте связь N=N0*2^(-t/T). Выразите искомую величину до подстановки чисел. Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество."],"answerSpec":{"kind":"number","value":92,"unit":""},"hint":"Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество.","source":"Физика с котом: Ядро и радиоактивность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Ядро и радиоактивность"},{"id":"ege-physics-27-meaning-0","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность: объясни формулу N=N0*2^(-t/T). Что означают величины и когда её применять?","back":"Эн равно эн нулевое умножить на два в степени минус тэ маленькое делить на тэ большое.\n\nN: среднее число оставшихся ядер; N₀: начальное число; t: прошедшее время; T: период полураспада.\n\nВремя t и период T являются разными величинами. За каждый период остаётся половина оставшихся ядер.","formula":"N=N0*2^(-t/T)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество.","source":"Физика с котом: Ядро и радиоактивность","objective":"Ядро и радиоактивность"},{"id":"ege-physics-27-meaning-1","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность: объясни формулу E=dm*c^2. Что означают величины и когда её применять?","back":"Энергия связи равна дефекту массы, умноженному на скорость света в квадрате.\n\nE: энергия связи; Δm: сумма масс свободных нуклонов минус масса ядра; c: скорость света.\n\n1 атомная единица массы соответствует примерно 931,5 МэВ энергии.","formula":"E=dm*c^2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"Сначала посчитай число периодов. Каждый раз дели на два оставшееся количество.","source":"Физика с котом: Ядро и радиоактивность","objective":"Ядро и радиоактивность"},{"id":"ege-physics-27-notes","topic":"ЕГЭ Физика · Квантовая физика","front":"Ядро и радиоактивность: какие условия применимости и типичные ошибки нужно помнить?","back":"Протонов Z, нейтронов A-Z. α: A-4, Z-2. β⁻: A неизменно, Z+1 (испускаются электрон и антинейтрино); γ не меняет A и Z. Eсв = Δmc², 1 а.е.м. соответствует 931,5 МэВ. В реакциях сохраняются заряд и нуклонное число. Деление тяжёлых и синтез лёгких ядер могут выделять энергию за счёт роста энергии связи на нуклон.","source":"Физика с котом: Ядро и радиоактивность","objective":"Ядро и радиоактивность"}]},{"id":"topic-28","name":"Относительность","section":"Современная физика","cards":[{"id":"ege-physics-28-formula","topic":"ЕГЭ Физика · Современная физика","front":"Относительность\nЗапиши энергию покоя E0 тела массы m через скорость света c.","back":"Ответ: E0=m*c^2.\n\nE₀ = mc². Масса m здесь инвариантная. Полная энергия движущегося тела E = γmc².","hints":["Определите, какие величины связывает закон. Проверьте, в каких единицах измеряется искомая величина."],"answerSpec":{"kind":"formula","index":28},"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","formula":"E0=m*c^2","formulaSide":"back","source":"Физика с котом: Относительность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Относительность"},{"id":"ege-physics-28-easy","topic":"ЕГЭ Физика · Современная физика","front":"Относительность\nВо сколько раз увеличится энергия покоя при увеличении массы в 2 раза?","back":"Ответ: 2 раза.\n\nE₀ ∝ m при постоянной c. Энергия удваивается.","hints":["Раздел «Относительность». Отделите искомую величину от данных условия. Ответ требуется в раза.","Используйте связь E0=m*c^2. Выразите искомую величину до подстановки чисел. В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶."],"answerSpec":{"kind":"number","value":2,"unit":"раза"},"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","source":"Физика с котом: Относительность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Относительность"},{"id":"ege-physics-28-task","topic":"ЕГЭ Физика · Современная физика","front":"Относительность\nДефект массы системы 0,001 кг. Найди выделившуюся энергию в единицах 10¹³ Дж. c = 3·10⁸ м/с.","back":"Ответ: 9 ×10¹³ Дж.\n\nΔE = Δmc² = 0,001·(3·10⁸)² = 9·10¹³ Дж. В указанных единицах ответ 9.","hints":["Раздел «Относительность». Отделите искомую величину от данных условия. Ответ требуется в ×10¹³ Дж.","Используйте связь E0=m*c^2. Выразите искомую величину до подстановки чисел. В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶."],"answerSpec":{"kind":"number","value":9,"unit":"×10¹³ Дж"},"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","source":"Физика с котом: Относительность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Относительность"},{"id":"ege-physics-28-bonus","topic":"ЕГЭ Физика · Современная физика","front":"Относительность · Повышенная сложность\nЧасы движутся относительно лаборатории со скоростью 0,6c. Между двумя событиями на этих часах прошло 8 с. Сколько времени между событиями прошло в лаборатории?","back":"Ответ: 10 с.\n\nСобственное время Δτ = 8 с. γ = 1/√(1-0,6²) = 1/0,8 = 1,25. Δt = γΔτ = 10 с.","hints":["Раздел «Относительность». Отделите искомую величину от данных условия. Ответ требуется в с.","Используйте связь E0=m*c^2. Выразите искомую величину до подстановки чисел. В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶."],"answerSpec":{"kind":"number","value":10,"unit":"с"},"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","source":"Физика с котом: Относительность","sourceUrl":"https://fizika-kot-laboratoriya.a9507652513.chatgpt.site/","objective":"Относительность"},{"id":"ege-physics-28-meaning-0","topic":"ЕГЭ Физика · Современная физика","front":"Относительность: объясни формулу E0=m*c^2. Что означают величины и когда её применять?","back":"Энергия покоя равна эм цэ в квадрате.\n\nE₀: энергия покоя; m: инвариантная масса; c: скорость света в вакууме.\n\nЭто энергия даже неподвижного в выбранной системе тела.","formula":"E0=m*c^2","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","source":"Физика с котом: Относительность","objective":"Относительность"},{"id":"ege-physics-28-meaning-1","topic":"ЕГЭ Физика · Современная физика","front":"Относительность: объясни формулу gamma=1/sqrt(1-v^2/c^2). Что означают величины и когда её применять?","back":"Гамма равно единице на корень из единицы минус вэ в квадрате на цэ в квадрате.\n\nγ (гамма): фактор Лоренца; v: относительная скорость; c: скорость света.\n\nПри малой по сравнению с c скорости γ близка к единице.","formula":"gamma=1/sqrt(1-v^2/c^2)","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","source":"Физика с котом: Относительность","objective":"Относительность"},{"id":"ege-physics-28-meaning-2","topic":"ЕГЭ Физика · Современная физика","front":"Относительность: объясни формулу t=gamma*tau. Что означают величины и когда её применять?","back":"Лабораторное время равно гамма умножить на собственное время.\n\nt: интервал в лаборатории; τ (тау): интервал по часам, движущимся вместе с объектом.\n\nСравниваются одни и те же два события.","formula":"t=gamma*tau","formulaSide":"front","hints":["Назовите каждую букву и её единицу измерения. Затем объясните словами связь величин.","Подумайте, какие условия нужны для этого закона: система отсчёта, постоянство величин или свойства среды."],"hint":"В mc² скорость света возводится в квадрат целиком: (3·10⁸)² = 9·10¹⁶.","source":"Физика с котом: Относительность","objective":"Относительность"},{"id":"ege-physics-28-notes","topic":"ЕГЭ Физика · Современная физика","front":"Относительность: какие условия применимости и типичные ошибки нужно помнить?","back":"Законы физики одинаковы во всех инерциальных системах, скорость света в вакууме одинакова для всех инерциальных наблюдателей. γ = 1/√(1-v²/c²). При v ≪ c результаты переходят в классическую механику.","source":"Физика с котом: Относительность","objective":"Относительность"}]}],"total":234};